def _auto_install_enabled(config=None) -> bool:
    """Auto-install is ON by default. Disable with MCX_ALLOW_AUTO_INSTALL=0.
    There is no separate testnet/mainnet mode; config is unused here."""
    import os
    raw = os.environ.get("MCX_ALLOW_AUTO_INSTALL", "").strip().lower()
    if raw in ("0", "false", "no", "off"):
        return False
    if raw in ("1", "true", "yes", "on"):
        return True
    return True

def _ensure_dependencies() -> None:
    import os, sys
    if os.environ.get("MCX_SKIP_AUTO_INSTALL", "").strip().lower() in ("1", "true", "yes", "on"):
        print("[MCX] Dependency auto-install skipped (environment override).", file=sys.stderr)
        return
    try:
        import importlib.util as _ilu
    except Exception:
        return

    def _absent():
        out = []
        for imp, pip_name, required in _DEPS:
            if imp == "uvloop" and sys.platform == "win32":
                continue
            try:
                found = _ilu.find_spec(imp) is not None
            except Exception:
                found = False
            if not found:
                out.append((pip_name, required))
        return out

    missing = _absent()
    if not missing:
        return
    required_missing = [p for p, req in missing if req]
    optional_missing = [p for p, req in missing if not req]
    if required_missing:
        print("[MCX] Missing required Python packages: " + ", ".join(required_missing),
              file=sys.stderr)
    if optional_missing:
        print("[MCX] Missing optional Python packages: " + ", ".join(optional_missing),
              file=sys.stderr)
    if not missing:
        return
    try:
        ans = input("[MCX] Install missing Python packages now? (y/n): ").strip().lower()
    except EOFError:
        if False:
            ans = "y"
        else:
            print("[MCX] Auto-install declined (non-interactive, no MCX_ALLOW_AUTO_INSTALL=1).",
                  file=sys.stderr)
            required_missing = [p for p, req in missing if req]
            if required_missing:
                print("[MCX] FATAL: required packages missing: "
                      + ", ".join(required_missing), file=sys.stderr)
                sys.exit(1)
            return
    if ans not in ("y", "yes"):
        required_missing = [p for p, req in missing if req]
        if required_missing:
            print("[MCX] FATAL: required packages missing: "
                  + ", ".join(required_missing), file=sys.stderr)
            sys.exit(1)
        print("[MCX] Optional packages unavailable (some features stay disabled).",
              file=sys.stderr)
        return
    # wheel) must not hide the rest, which is what happened when the whole set
    import subprocess, tempfile
    def _norm(name):
        return name.strip().lower().replace("_", "-")
    _pg = {"psycopg2-binary", "asyncpg"}
    _pg_opt_in = os.environ.get("MCX_INSTALL_PG_DRIVERS", "").strip().lower() in ("1", "true", "yes", "on")
    _termux = sys.platform == "android" or "com.termux" in os.environ.get("PREFIX", "")
    required_names = [p for p, req in missing if req]
    optional_names = [p for p, req in missing
                      if not req
                      and (_pg_opt_in or _norm(p) not in {_norm(x) for x in _pg})
                      and not (_termux and _norm(p) == "uvloop")]
    print("[MCX] Installing missing Python packages: " + ", ".join(required_names + optional_names),
          file=sys.stderr)

    def _pip(args):
        try:
            r = subprocess.run([sys.executable, "-m", "pip", "install", "--prefer-binary", *args],
                               timeout=900)
            return r.returncode == 0
        except Exception as e:
            print(f"[MCX] pip error: {e}", file=sys.stderr)
            return False


    if required_names:
        done = False
        _manifest = os.path.join(os.path.dirname(os.path.abspath(__file__)), "requirements-mcx78.txt")
        if os.path.exists(_manifest):
            _req_set = {_norm(pip) for _imp, pip, req in _DEPS if req}
            _keep = []
            with open(_manifest, encoding="utf-8") as _mf:
                for _line in _mf:
                    _raw = _line.strip()
                    if not _raw or _raw.startswith("#"):
                        continue
                    _nm = _raw
                    for _sep in ("==", ">=", "<=", "~=", "!=", ">", "<", "[", ";", " "):
                        _nm = _nm.split(_sep)[0]
                    if _norm(_nm) in _req_set:
                        _keep.append(_raw)
            if _keep:
                _tf = tempfile.NamedTemporaryFile("w", suffix=".txt", delete=False, encoding="utf-8")
                _tf.write("\n".join(_keep) + "\n")
                _tf.close()
                try:
                    done = _pip(["-r", _tf.name])
                finally:
                    try:
                        os.unlink(_tf.name)
                    except OSError:
                        pass
        if not done:
            for _name in required_names:
                if not _pip([_name]):
                    print(f"[MCX] could not install required package: {_name}", file=sys.stderr)
                    if _termux:
                        print("[MCX] On Termux, packages that need Rust (for example pydantic-core, "
                              "pulled in by eth-utils 6.x) must be built with Termux's own toolchain. "
                              "Run: pkg install rust clang  then rerun node.py. Auto-install cannot "
                              "fix this by picking another version.", file=sys.stderr)

    for _name in optional_names:
        try:
            subprocess.run([sys.executable, "-m", "pip", "install", "--prefer-binary", _name], timeout=600)
        except Exception as e:
            print(f"[MCX] optional package {_name} not installed: {e}", file=sys.stderr)
    still_missing = _absent()
    required_missing = [p for p, req in still_missing if req]
    if required_missing:
        print("[MCX] FATAL: required packages still missing after install attempt: "
              + ", ".join(required_missing), file=sys.stderr)
        print("[MCX] Fix pip/network access and rerun, or set MCX_SKIP_AUTO_INSTALL=1 "
              "if you manage dependencies yourself.", file=sys.stderr)
        sys.exit(1)
    if still_missing:
        print("[MCX] Optional packages unavailable (some features stay disabled): "
              + ", ".join(p for p, _ in still_missing), file=sys.stderr)


_ensure_dependencies()
