SHRINK_INTERVAL = 100
SHRINK_INTERVAL_SEC = 3600
ACTIVE_MINER_WINDOW_BLOCKS = 5  # consensus constant: eligible if active in last K blocks

LOTTERY_SCALE = int(CONFIG['consensus'].get('lottery_scale', 1 << 249))
ATTEST_FRESH_BUFFER = int(CONFIG['consensus'].get('attest_fresh_buffer', 5))
ATTEST_GROWTH_PER_BLOCK = int(CONFIG['consensus'].get('attest_growth_per_block', 5))
SLOT_TIMEOUT = int(CONFIG['consensus'].get('slot_timeout', 30))

# (I-): the consensus parameters that must never
# config in one process. apply_consensus_config re-derives the globals
# from the effective config; check_consensus_params binds them to the
CONSENSUS_PARAM_KEYS = ("lottery_scale", "attest_fresh_buffer",
                        "attest_growth_per_block", "slot_timeout")


def _consensus_defaults():
    _c = DEFAULT_CONFIG.get('consensus', {})
    return {"lottery_scale": int(_c.get('lottery_scale', 1 << 249)),
            "attest_fresh_buffer": int(_c.get('attest_fresh_buffer', 5)),
            "attest_growth_per_block": int(_c.get('attest_growth_per_block', 5)),
            "slot_timeout": int(_c.get('slot_timeout', 30))}


def _validate_lottery_value(name, v, minimum: int) -> int:
    """CONFIG-VALID-1 (MCX80): strict lottery-parameter validation. Only
    genuine ints at or above the protocol minimum are accepted; bools,
    strings, floats, None and out-of-range values raise ValueError with the
    offending value named. Bounds from protocol use: lottery_scale is a
    positive scale (>= 1); attest buffers are additive caps (>= 0);
    slot_timeout divides elapsed time in the producer rank ladder
    (0 would ZeroDivision-crash it), so slot_timeout >= 1."""
    if isinstance(v, bool) or not isinstance(v, int):
        raise ValueError(f"config consensus.{name} must be an int >= {minimum}, got {v!r}")
    if v < minimum:
        raise ValueError(f"config consensus.{name} must be an int >= {minimum}, got {v!r}")
    return v


def _strict_bool(name, v, default=False) -> bool:
    """CONFIG-BOOL-1 (MCX80): centralized strict Boolean parsing. Actual
    bools pass through; only the documented strings "true"/"false"
    (case-insensitive, surrounding whitespace tolerated) are accepted.
    None means absent -> default. Anything else (numbers, unknown strings,
    lists, ...) raises ValueError. In particular the text "false" NEVER
    enables the flag (plain bool("false") is True — the bug this replaces)."""
    if v is None:
        return default
    if isinstance(v, bool):
        return v
    if isinstance(v, str):
        s = v.strip().lower()
        if s == "true":
            return True
        if s == "false":
            return False
    raise ValueError(f"config {name} must be a boolean (true/false), got {v!r}")


def apply_consensus_config(config) -> dict:
    """Re-derive EVERY consensus-effectual global from the effective config.

    CONFIG-APPLY-1 (MCX80 audit): the globals are now assigned FROM the same
    validated record the genesis uses (_consensus_record_from_config), so the
    two can never resolve a config differently. Previously absent keys kept
    whatever the globals held (a stale import-time/previous value) while the
    genesis record resolved them to defaults, and a late invalid value left
    earlier keys half-applied. Now: (1) every present value is validated and
    every absent/None value resolves to its default BEFORE any global changes
    (all-or-nothing), (2) globals == record by construction.

    GENESIS-VAL-3: the validator set is validated strictly first
    (validate_validators_config raises on a non-list/malformed key — never
    silent open mode) and applied with the rest. Present-but-invalid values
    raise ValueError (main() exits with a clear message); returns the applied
    mapping (recorded into fresh genesis files for genesis binding)."""
    global LOTTERY_SCALE, ATTEST_FRESH_BUFFER, ATTEST_GROWTH_PER_BLOCK, SLOT_TIMEOUT, VALIDATORS
    global MAX_MISSES, BAN_DURATION, PRUNE_BLOCKS, WALL_DENSITY_3D
    global GAS_PRICE, GAS_LIMIT_DEFAULT, MAX_BYTECODE
    global MAX_BLOCK_GAS, MAX_BLOCK_TXS, HTLC_V1_ENABLED
    _c = (config or {}).get('consensus', {}) or {}
    _vals = validate_validators_config(_c.get('validators'))
    rec = _consensus_record_from_config(config)
    LOTTERY_SCALE = rec["lottery_scale"]
    ATTEST_FRESH_BUFFER = rec["attest_fresh_buffer"]
    ATTEST_GROWTH_PER_BLOCK = rec["attest_growth_per_block"]
    SLOT_TIMEOUT = rec["slot_timeout"]
    VALIDATORS = _vals
    MAX_MISSES = rec["max_misses"]
    BAN_DURATION = rec["ban_duration"]
    PRUNE_BLOCKS = rec["prune_blocks"]
    WALL_DENSITY_3D = rec["wall_density_3d"]
    GAS_PRICE = rec["gas_price"]
    GAS_LIMIT_DEFAULT = rec["gas_limit_default"]
    MAX_BYTECODE = rec["max_bytecode"]
    MAX_BLOCK_GAS = rec["max_block_gas"]
    MAX_BLOCK_TXS = rec["max_block_txs"]
    HTLC_V1_ENABLED = rec["htlc_v1_enabled"]
    return {"lottery_scale": LOTTERY_SCALE,
            "attest_fresh_buffer": ATTEST_FRESH_BUFFER,
            "attest_growth_per_block": ATTEST_GROWTH_PER_BLOCK,
            "slot_timeout": SLOT_TIMEOUT,
            "validators": sorted(_effective_validators()),
            "max_misses": int(MAX_MISSES),
            "ban_duration": int(BAN_DURATION),
            "prune_blocks": int(PRUNE_BLOCKS),
            "wall_density_3d": float(WALL_DENSITY_3D),
            "gas_price": int(GAS_PRICE),
            "gas_limit_default": int(GAS_LIMIT_DEFAULT),
            "max_bytecode": int(MAX_BYTECODE),
            "max_block_gas": int(MAX_BLOCK_GAS),
            "max_block_txs": int(MAX_BLOCK_TXS),
            "htlc_v1_enabled": bool(HTLC_V1_ENABLED)}


def check_consensus_params(config, genesis_data):
    """Bind the effective config to the genesis consensus record (Fix 2).

    Compares the FULL ruleset (_consensus_record_from_config: every
    operator-settable validity/execution/eligibility/fork-choice value plus
    code anchors — see its docstring for the bound/excluded audit) against
    the file's record. Returns (True, reason); reason is "ok" or
    "grandfathered-no-record" (files predating any record warn but boot —
    unreachable via the genesis_export_verified startup gate, which refuses
    record-less files at the identity layer first; kept as defense in
    depth). A mismatch refuses to run mixed rules for one chain:
    (False, "<dotted.key> mismatch: ...") naming the exact key.
    """
    try:
        _want = _consensus_record_from_config(config)
    except (TypeError, ValueError):
        return False, "unparseable consensus config"
    _rec = (genesis_data or {}).get('consensus') if isinstance(genesis_data, dict) else None
    if not isinstance(_rec, dict):
        return True, "grandfathered-no-record"

    # B1: prune_blocks is a LOCAL retention policy, not a consensus
    # nodes with different prune windows must be able to join the same
    # every other consensus key must still match exactly. Caveat: the prune
    # local safety limit, not a difference in block validity.
    _want = {k: v for k, v in _want.items() if k != "prune_blocks"}
    _rec = {k: v for k, v in _rec.items() if k != "prune_blocks"}

    def _diff(path, want, got):
        if isinstance(want, dict):
            if not isinstance(got, dict):
                return f"{path or 'consensus'} missing/unparseable in genesis record"
            for _k in want:
                _r = _diff(f"{path}.{_k}" if path else str(_k), want[_k], got.get(_k))
                if _r:
                    return _r
            return ""
        if got != want:
            return f"{path} mismatch: config={want!r} genesis={got!r}"
        return ""
    _reason = _diff("", _want, _rec)
    if _reason:
        return False, _reason
    return True, "ok"


def _normalize_validator_key(v) -> str:
    """Canonical validator key form: string, lowercased, 0x prefix stripped."""
    s = str(v).strip().lower()
    if s.startswith("0x"):
        s = s[2:]
    return s


def _normalize_validator_list(vals) -> list:
    """Sorted canonical validator list from a config value. Non-list
    values and falsy entries yield []. Duplicates are NOT deduplicated
    here (they collapse in the frozenset); sorting keeps the genesis
    record deterministic."""
    try:
        if not isinstance(vals, (list, tuple)):
            return []
        # dedupe so _consensus_record_from_config (config) and
        # _effective_consensus_ruleset (frozenset) always agree. Previously a
        # duplicate entry made check_consensus_params refuse to boot the
        return sorted({_normalize_validator_key(v) for v in vals if v})
    except Exception:
        return []

_VALIDATOR_KEY_RE = re.compile(r"^04[0-9a-f]{128}$")


def validate_validators_config(raw) -> list:
    """GENESIS-VAL-2: strict, fail-closed validation of consensus.validators.

    The tolerant normalizer above silently maps a non-list (e.g. a single
    YAML string, the natural way to write ONE validator) to [] = open mode
    where ANY key may produce blocks, and silently accepts malformed keys
    that can never match. Both are consensus-affecting misconfigurations,
    so startup refuses them. None / [] is the explicit open mode (warned
    elsewhere; refused on mainnet). Returns the canonical sorted list."""
    if raw is None:
        return []
    if not isinstance(raw, (list, tuple)):
        raise ValueError(
            "consensus.validators must be a YAML LIST of public keys "
            f"(got {type(raw).__name__}); a single key still needs list syntax: '- 04ab...'")
    out = set()
    for i, v in enumerate(raw):
        if not isinstance(v, str):
            raise ValueError(f"consensus.validators[{i}] must be a string public key")
        k = _normalize_validator_key(v)
        if not _VALIDATOR_KEY_RE.fullmatch(k):
            raise ValueError(
                f"consensus.validators[{i}] is not an uncompressed secp256k1 public key "
                f"(expected '04' + 128 hex chars, got {len(k)} chars)")
        out.add(k)
    return sorted(out)


def _effective_validators() -> frozenset:
    """C1 — OPEN MINING: the fixed producer set is unconditionally empty.

    Restricting block production to a configured validator set is no
    longer supported. Any connected maze strictly larger than
    MIN_MAZE_SIZE that passes its own per-maze lottery threshold may
    produce (D1/D2). The verifier, fork-weight and append-side checks
    that consult this set therefore become no-ops; they are left in
    place so the code reads correctly if a future owner reintroduces a
    set. Returns frozenset() in O(1)."""
    return frozenset()


_VALIDATOR_MODE_WARNED = False


def _validator_boot_mode() -> str:
    """'open' always (C1 — open mining). A one-time WARNING is logged at
    startup when consensus.validators still carries entries: they are
    ignored. Called at node start; unit-testable without booting."""
    global _VALIDATOR_MODE_WARNED
    _configured = []
    try:
        _configured = _normalize_validator_list(VALIDATORS or [])
    except Exception:
        _configured = []
    if _configured and not _VALIDATOR_MODE_WARNED:
        _VALIDATOR_MODE_WARNED = True
        logger.warning("[VALIDATORS] consensus.validators lists %d producer key(s) but open mining is "
                       "in effect (C1): the producer set is ignored and any eligible maze may produce.",
                       len(_configured))
    return "open"


EXPECTED_GENESIS_PIN = None


def _expected_genesis_pin(config):
    """Return the validated pin (lowercase hex) or None if unset.
    Raises ValueError for a present-but-malformed value (fail closed)."""
    raw = ((config or {}).get('p2p') or {}).get('expected_genesis_hash', None)
    if raw is None:
        _code_pin = (TESTNET_GENESIS_HASH or "").strip().lower()
        if _code_pin:
            if len(_code_pin) != 64 or any(c not in "0123456789abcdef" for c in _code_pin):
                raise ValueError("TESTNET_GENESIS_HASH must be exactly 64 hex characters")
            return _code_pin
        return None
    if not isinstance(raw, str):
        raise ValueError("p2p.expected_genesis_hash must be a string of 64 hex characters")
    v = raw.strip().lower()
    if len(v) != 64 or any(c not in "0123456789abcdef" for c in v):
        raise ValueError("p2p.expected_genesis_hash must be exactly 64 hex characters")
    return v


def _genesis_pin_failure(gh, pin):
    """None when the peer genesis hash satisfies the pin (or no pin is set)."""
    if pin is None:
        return None
    if str(gh or "").strip().lower() != pin:
        return (f"peer genesis {str(gh or '')[:16]} does not match pinned "
                f"p2p.expected_genesis_hash {pin[:16]}")
    return None


def _update_genesis_pin_in_file(new_hash):
    """After creating a fresh genesis, update the in-source genesis pin
    (TESTNET_GENESIS_HASH) in this node file to the new hash, so the file
    the operator distributes to followers pins the chain they will join.
    Without this, followers' pin check would refuse the fresh genesis
    (their file pins the previous chain). Atomic write (temp + replace);
    never raises — on failure it logs a warning with the hash the operator
    must set as p2p.expected_genesis_hash instead. The running process is
    unaffected (already loaded); only the file on disk changes."""
    global TESTNET_GENESIS_HASH
    _new = str(new_hash or "").strip().lower()
    if len(_new) != 64 or any(c not in "0123456789abcdef" for c in _new):
        return
    if (TESTNET_GENESIS_HASH or "").strip().lower() == _new:
        return
    try:
        _src = os.path.abspath(__file__)
        with open(_src, "rb") as _f:
            _data = _f.read()
        _old_line = ('TESTNET_GENESIS_HASH = "' + (TESTNET_GENESIS_HASH or "").strip() + '"').encode("utf-8")
        if _data.count(_old_line) != 1:
            raise RuntimeError("pin line not found exactly once")
        _new_line = ('TESTNET_GENESIS_HASH = "' + _new + '"').encode("utf-8")
        _data = _data.replace(_old_line, _new_line)
        _tmp = _src + ".tmp-pin"
        with open(_tmp, "wb") as _f:
            _f.write(_data)
        os.replace(_tmp, _src)
        TESTNET_GENESIS_HASH = _new
        logger.info("[GENESIS] genesis pin updated in %s to %s... (distribute this file to followers)", _src, _new[:16])
    except Exception as _e:
        logger.warning("[GENESIS] could not update the genesis pin in the node file (%s); followers must set p2p.expected_genesis_hash to %s", _e, _new)


def _mainnet_guard_failures(config, allow_new_genesis=False) -> list:
    """The one node profile: mainnet. There is no testnet mode.
    Empty list = clear to boot; every entry is a refusal reason.
    allow_new_genesis=True is the one-time genesis creator: it has no genesis
    hash to pin yet, so the pin is exempt for that start only."""
    _cfg = config or {}
    failures = []
    _db_url = str((_cfg.get('database') or {}).get('url', '') or '')
    if _db_url.startswith('postgresql://'):
        if os.environ.get("MCX_PG_PASSWORD") in (None, "", "postgres"):
            failures.append("MCX_PG_PASSWORD must be set to a non-default value")
        if os.environ.get("MCX_DB_PASS") in (None, "", "postgres"):
            failures.append("MCX_DB_PASS must be set to a non-default value")
    _vm = _cfg.get('vm') or {}
    if not bool(_vm.get('require_sandbox', False)):
        failures.append("vm.require_sandbox must be true")
    if sys.platform == "win32" and bool(_vm.get('require_sandbox', False)):
        _ov = os.environ.get("MCX_ALLOW_UNSANDBOXED_VM", "").strip().lower()
        if _ov not in ("1", "true", "yes", "on"):
            try:
                _ans = input("[SANDBOX] Windows VM worker is not isolated. Accept this risk? (y/n): ").strip().lower()
            except EOFError:
                _ans = ""
            if _ans not in ("y", "yes"):
                failures.append("on Windows the VM worker is not isolated: run on Linux, or set "
                                "MCX_ALLOW_UNSANDBOXED_VM=1 to accept that risk knowingly")
    try:
        if _expected_genesis_pin(_cfg) is None and not allow_new_genesis:
            failures.append("p2p.expected_genesis_hash must be set (64 hex chars) unless this is the genesis creator")
    except ValueError as _pe:
        failures.append(str(_pe))
    _rtl = (_cfg.get('node') or {}).get('rpc_trust_loopback', True)
    if _rtl is None or bool(_rtl):
        failures.append("node.rpc_trust_loopback must be false")
    return failures


def _maze_att_weight(size) -> int:
    """IDEA5-ATTEST lottery weight for an attested maze size (size^3 - 5^3)."""
    if isinstance(size, float) and not math.isfinite(size):
        return 0
    try:
        size = int(size)
    except (TypeError, ValueError, OverflowError):
        return 0
    return 0 if size <= MIN_MAZE_SIZE else size ** 3 - MIN_MAZE_SIZE ** 3

TICKET_DOMAIN_MAX = (1 << 256) - 1


def _maze_threshold(size) -> int:
    """LOTTERY-SCALE-1: ticket < threshold wins the lottery for this size.

    MCX79 asymptotic gate (chain reset, ruleset v3): pass probability
    p(size) = 1 - MIN_MAZE_SIZE^3 / size^3, evaluated as an integer
    threshold over the 256-bit ticket domain. Strictly increasing in
    size, strictly below TICKET_DOMAIN_MAX for every finite integer
    size — no size ever reaches 100% ("larger maze, higher chance, no
    max, never 100%"). Integer arithmetic only: no floats anywhere on
    this path. Fork weight (_maze_att_weight, cubic, unbounded by
    design) is a separate mechanism and is NOT capped. LOTTERY_SCALE
    itself is frozen (no longer consumed here; retained for record
    compatibility).
    """
    try:
        size = int(size)
    except (TypeError, ValueError, OverflowError):
        return 0
    if size <= MIN_MAZE_SIZE:
        return 0
    denom = size ** 3
    return TICKET_DOMAIN_MAX - (MIN_MAZE_SIZE ** 3 * TICKET_DOMAIN_MAX) // denom

def _maze_ticket(prev_hash: str, height: int, maze_id: str, ts=0) -> int:
    """Deterministic ticket: int(keccak(prev_hash || height || ts || maze_id)).

    LIVENESS-TICKET-TS-1: `ts` is the proposed block timestamp in integer
    seconds. Binding the ticket to the block's own timestamp makes every
    retry (a new `now`, hence a new candidate timestamp) a fresh draw while
    remaining fully deterministic: every verifier recomputes it from the
    sealed block. Previously the ticket was frozen for a given
    (parent, height, maze_id), so an unlucky candidate set could stall that
    height forever (size-6 pass probability is only ~42%).
    """
    height_i = int(height)
    try:
        ts_i = int(ts)
    except (TypeError, ValueError, OverflowError):
        ts_i = int(float(ts))
    if height_i < 0 or ts_i < 0 or ts_i >= (1 << 64):
        raise ValueError("height/ts out of ticket domain")
    return int.from_bytes(
        eth_keccak(bytes.fromhex(prev_hash) + height_i.to_bytes(8, "big")
                   + ts_i.to_bytes(8, "big") + str(maze_id).encode()),
        "big")

def _block_att_weight(block: dict) -> int:
    """IDEA5-CHAINWEIGHT-1: per-block fork-choice weight = its attestation weight.

    MCX79: blocks attested by keys outside the configured validator set
    contribute zero fork weight (defense in depth alongside the
    verify/append rejections). Empty set = open mode, unchanged."""
    att = block.get("maze_attestation")
    if not isinstance(att, dict):
        return 0
    _validators = _effective_validators()
    if _validators and _normalize_validator_key(att.get("pubkey", "")) not in _validators:
        return 0
    return _maze_att_weight(att.get("size", 0))


def _fork_tiebreak_winner(our_tip: str, their_tip: str) -> bool:
    """R4-fork-tie-hashbreak: equal-weight fork rule — the LARGER hex tip
    hash wins (Bitcoin shape). Deterministic across nodes, unlike
    first-seen. Equal hashes mean the same tip: keep ours (False)."""
    return str(their_tip or "") > str(our_tip or "")

def _gas_ceiling(gas_in) -> int:
    """GAS-USED-1 / v9.3: parse client-supplied gas with NO cap.
    --gas is a cap the sender chooses; there is no protocol max
    per-tx gas. The block gas limit (MAX_BLOCK_GAS) is the bound
    on what can be sealed. Negative / unparseable -> default."""
    try:
        g = GAS_LIMIT_DEFAULT if gas_in is None else gas_in
        if isinstance(g, str):
            g = int(g, 16) if g.lower().startswith('0x') else int(g)
        g = int(g)
    except (TypeError, ValueError):
        g = GAS_LIMIT_DEFAULT
    return max(0, g)

VM_GAS_TX_TYPES = ('contract_deploy', 'contract_call', 'htlc_create')

def _gas_data_cost(data_bytes) -> int:
    """Ethereum calldata cost: 4 per zero byte, 16 per non-zero byte."""
    if not data_bytes:
        return 0
    _z = data_bytes.count(0)
    return _z * GAS_PER_ZERO_BYTE + (len(data_bytes) - _z) * GAS_PER_NONZERO_BYTE

def _gas_data_bytes(d) -> bytes:
    """Data field -> bytes, robust to every form a tx carries it in
    (raw bytes, 0x-hex string, plain hex string, {'raw': ...}).
    NOTE: tx_data_to_bytes() stringifies raw bytes (str(b'..') is
    35 chars), so it must NOT be used on a bytes value."""
    if d is None:
        return b''
    if isinstance(d, bytes):
        return d
    if isinstance(d, dict):
        return _gas_data_bytes(d.get('raw', ''))
    if isinstance(d, str):
        _s = d[2:] if d.startswith(('0x', '0X')) else d
        if not _s:
            return b''
        try:
            return bytes.fromhex(_s)
        except ValueError:
            return d.encode()
    return tx_data_to_bytes(d)

def _gas_intrinsic(tx) -> int:
    """Ethereum intrinsic gas for a tx: 21000 base + calldata cost
    + 32000 when it creates a contract. Pure function of the tx
    fields (no DB, no clock) so producer and followers agree."""
    _t = str(tx.get('tx_type', 'send')) if isinstance(tx, dict) else 'send'
    _cost = GAS_BASE_COST
    _data = None
    if isinstance(tx, dict):
        if _t == 'contract_deploy':
            _cost += GAS_CREATE_COST
            _raw = tx.get('bytecode', tx.get('data'))
            _data = _gas_data_bytes(_raw) if _raw is not None else b''
        elif _t in ('contract_call', 'htlc_create'):
            _raw = tx.get('data', tx.get('input', b''))
            _data = _gas_data_bytes(_raw) if _raw is not None else b''
        elif tx.get('data') is not None:
            _data = _gas_data_bytes(tx.get('data'))
    if _data:
        _cost += _gas_data_cost(_data)
    return _cost

def _gas_price_of(tx) -> int:
    """Sender-chosen gasPrice for a tx (no protocol min/max).
    Missing / unparseable / negative -> default GAS_PRICE (1)."""
    try:
        _p = tx.get('gasPrice', tx.get('gas_price', GAS_PRICE)) if isinstance(tx, dict) else GAS_PRICE
        _p = int(_p)
    except (TypeError, ValueError):
        _p = GAS_PRICE
    return _p if _p >= 0 else GAS_PRICE

def _tx_declared_gas(tx) -> int:
    """Gas counted against the block gas limit for a tx: its gas
    LIMIT (cap), so the limit bounds the maximum work a block can
    contain. Every tx counts at least its intrinsic cost (a plain
    send counts 21000, not 0 — the old code counted 0 for non-VM
    txs, so sends did not count toward the block gas limit)."""
    if not isinstance(tx, dict):
        raise ValueError("transaction is not an object")
    if tx.get('tx_type') in VM_GAS_TX_TYPES:
        return _gas_ceiling(tx.get('gas', GAS_LIMIT_DEFAULT))
    _g = tx.get('gas')
    if _g is None:
        return _gas_intrinsic(tx)
    try:
        _g = int(_g, 16) if isinstance(_g, str) and _g.lower().startswith('0x') else int(_g)
    except (TypeError, ValueError):
        return _gas_intrinsic(tx)
    return max(_gas_intrinsic(tx), _g)

def _block_limits_ok(tx_list):
    """(ok, reason): len(txs) <= MAX_BLOCK_TXS and sum(declared gas) <= MAX_BLOCK_GAS."""
    try:
        txs = tx_list or []
        if len(txs) > MAX_BLOCK_TXS:
            return False, f"{len(txs)} txs > MAX_BLOCK_TXS {MAX_BLOCK_TXS}"
        total = 0
        for t in txs:
            total += _tx_declared_gas(t)
            if total > MAX_BLOCK_GAS:
                return False, f"declared gas {total} > MAX_BLOCK_GAS {MAX_BLOCK_GAS}"
        return True, ""
    except (TypeError, ValueError, OverflowError) as e:
        return False, f"malformed transactions: {e}"

BLOCK_CACHE_MAX = 10000
OFFLINE_DECAY_RATE = 0.25
GROWTH_DIFFICULTY_EXP = 0.1
MIN_WALL_DENSITY_PPM = 350000
DENSITY_INCREMENT_PPM = 35000
