def _valid_maze_size(v):
    """MAZE-MIN-1 (MCX80): single maze-dimension invariant — an int never
    below MIN_MAZE_SIZE (5 = 5x5x5 = 125 cells). Returns the int, or None
    for anything else (non-ints, bools, non-integral floats, undersized).
    Callers reject (verify) or skip/quarantine (apply/load); nobody
    clamps-and-continues a consensus input."""
    try:
        if isinstance(v, bool):
            return None
        n = int(v)
        if isinstance(v, float) and float(n) != float(v):
            return None
    except (TypeError, ValueError, OverflowError):
        return None
    if n < MIN_MAZE_SIZE:
        return None
    return n

def _last_updates_by_maze(updates) -> dict:
    """The LAST maze_update per maze inside ONE block's maze_updates.

    WORK-PROOF-2 (branch-scoped proof state): the single deterministic
    rule shared by every producer of branch-scoped state:
      * key = maze_id, falling back to miner_id — the same key
        _append_block applies the update under;
      * within one block the LAST update for a maze wins (the canonical
        _proven_update_size walk and _append_block's state application
        both take the last one; verify_block_proof verifies the last
        update per miner).

    Returns {maze_key: update_dict}.
    """
    out: dict = {}
    if not isinstance(updates, (list, tuple)):
        return out
    for _u in updates:
        if not isinstance(_u, dict):
            continue
        _mid = str(_u.get("maze_id") or _u.get("miner_id") or "")
        if not _mid:
            continue
        out[_mid] = _u
    return out

def _proven_sizes_from_updates(updates) -> dict:
    """Latest proven maze size per maze from ONE block's maze_updates.

    WORK-PROOF-2 (branch-scoped proof state): derived from
    _last_updates_by_maze so the proven-size map and the geometry map
    always describe the SAME update of a block. An update whose new_size
    is not a valid maze dimension contributes nothing (verification
    rejects such a block anyway).

    Returns {maze_key: proven_size}.
    """
    out: dict = {}
    for _mid, _u in _last_updates_by_maze(updates).items():
        _sz = _valid_maze_size(_u.get("new_size"))
        if _sz is not None:
            out[_mid] = _sz
    return out
