def _fixed_consensus_params() -> dict:
    """RULES-BIND-1 (MCX80): consensus-critical protocol literals in ONE
    place, merged into BOTH the config-derived record and the effective
    (live-global) record so genesis creation and verification cannot
    disagree about which rules are in effect. Every value here is consumed
    by a deterministic acceptance/execution path:
    economics.{genesis_supply (genesis alloc), max_supply (mint cap),
    initial_block_reward + halving_interval (subsidy schedule),
    subs (unit conversion)}, protocol.{min_maze_size (eligibility/weight/
    attestation),
    active_miner_window (eligibility window), block_future_skew (timestamp
    validity bound)}. Deliberately NOT bound (fixed but not validity
    predicates): BLOCK_TIME (seal pacing only), FINALITY_EPOCH_LENGTH
    (advisory checkpoints), MIN_STEP_INTERVAL (unused), POG_ACTIVATION_
    HEIGHT/SHRINK_* (local pacing/display). Token supply cap stays
    separate (TOKEN_MAX_SUPPLY, not native issuance)."""
    return {
        "genesis_supply": int(GENESIS_SUPPLY),
        "max_supply": int(MAX_SUPPLY),
        "initial_block_reward": int(INITIAL_BLOCK_REWARD),
        "halving_interval": int(HALVING_INTERVAL),
        "subs": int(SUBS),
        "min_maze_size": int(MIN_MAZE_SIZE),
        "token_transfer_fee_per_byte": int(TOKEN_TRANSFER_FEE_PER_BYTE),
        "token_transfer_v2": bool(TOKEN_FEE_V2_ENABLED),
        # GAS-USED-1 / v9.3: Ethereum intrinsic gas schedule + SVF fees.
        "gas_base_cost": int(GAS_BASE_COST),
        "gas_per_zero_byte": int(GAS_PER_ZERO_BYTE),
        "gas_per_nonzero_byte": int(GAS_PER_NONZERO_BYTE),
        "gas_create_cost": int(GAS_CREATE_COST),
        "gas_code_deposit_per_byte": int(GAS_CODE_DEPOSIT_PER_BYTE),
        "svf_fee_per_byte": int(TOKEN_TRANSFER_FEE_PER_BYTE),
        "svf_fee_base": int(SVF_FEE_BASE),
        "svf_fee_create": int(SVF_FEE_CREATE),
        "token_transfer_sig_wire_bytes": int(TOKEN_TRANSFER_SIG_WIRE_BYTES),
        "max_token_burn_bps": int(MAX_TOKEN_BURN_BPS),
        "active_miner_window": int(ACTIVE_MINER_WINDOW_BLOCKS),
        "block_future_skew": int(BLOCK_FUTURE_SKEW),
    }


def _consensus_record_from_config(config) -> dict:
    """Pure builder: the genesis consensus record for a config mapping.

    Covers every OPERATOR-SETTABLE value consumed by a validity, execution,
    activation, eligibility, fee-charging, or fork-choice path (Fix 2 audit):
    consensus.{max_misses (ban->eligibility 14895/3573/3563), ban_duration
    via p2p (miner ban length 13799/14890 — shared knob, bound once),
    prune_blocks (reorg bound 14680), wall_density_3d (maze contents 6992),
    lottery_scale/attest_fresh_buffer/attest_growth_per_block/slot_timeout
    (R9), htlc_v1_enabled (tx-type/precompile gating),
    validators (MCX79 fixed producer set: sorted canonical pubkeys)},
    fees.{min_fee (fee floor 1707), token_creation_multiplier (1713)},
    vm.{gas_price (BASEFEE/charging), gas_limit_default (execution ceiling +
    admission 16433), max_bytecode (deploy validity)}, plus code anchors
    {version, chain_id} identifying the fixed protocol, plus the
    RULES-BIND-1 fixed literals (native economics, min_maze_size,
    active_miner_window, block_future_skew — merged
    from the single _fixed_consensus_params() source, so this record and
    the effective record agree by construction). Missing keys fall
    back to DEFAULT_CONFIG. Deliberately NOT bound (operator-local, no
    validity predicate reads them): ports/binds, peer discovery
    (genesis_node/dns/bootstrap/fallback), max_peers/ban_threshold,
    dht/discovery timers, epoch_length (local checkpoint cadence — the
    finalized flag is never validity-read), rbf_increment/max_tx_per_block/
    mempool max_size/expiry/max_nonce_gap (production/policy caps),
    sandbox/require_sandbox/timeout_seconds (local execution env),
    snapshot cadence, database/node/wallet keys. Deliberately NOT bound
    (dead keys, assigned never read): finality_threshold,
    initial/min/max_required_knowledge, knowledge_adjustment_interval,
    target_catch_time, base/min/max_maze_size_3d, maze_growth_rate (sizes
    are chain-agreed, _chain_agreed_maze_sizes), commit_reveal_activation_
    height, max_fee/fee_per_byte (removed R4), max_state_size, cpfp_min_fee,
    block_time/min_step_interval (dead; BLOCK_TIME literal frozen)."""
    _c = (config or {}).get('consensus', {}) or {}
    _v = (config or {}).get('vm', {}) or {}
    _p = (config or {}).get('p2p', {}) or {}
    _dc = DEFAULT_CONFIG.get('consensus', {})
    _dv = DEFAULT_CONFIG.get('vm', {})
    _dp = DEFAULT_CONFIG.get('p2p', {})
    try:
        _validators = _normalize_validator_list(
            _c.get('validators', _dc.get('validators', [])))
    except Exception:
        _validators = []
    _rec = {
        "ruleset_version": GENESIS_CONSENSUS_RULESET_VERSION,
        "max_misses": _rule_int('consensus.max_misses', _c.get('max_misses'), _dc.get('max_misses', 3)),
        "ban_duration": _rule_int('p2p.ban_duration', _p.get('ban_duration'), _dp.get('ban_duration', 3600)),
        "prune_blocks": _rule_int('consensus.prune_blocks', _c.get('prune_blocks'), _dc.get('prune_blocks', 10000)),
        "wall_density_3d": _rule_density(_c.get('wall_density_3d'), _dc.get('wall_density_3d', 0.55)),
        # GAS-USED-1 / v9.3: gas/fee values are HARDCODED protocol
        # constants. A config.yaml that sets them is ignored; the
        # record below uses the hardcoded values, so the effective
        # ruleset and the config-derived record always agree.
        "gas_price": int(GAS_PRICE),
        "gas_limit_default": int(GAS_LIMIT_DEFAULT),
        "max_bytecode": int(MAX_BYTECODE),
        "max_block_gas": int(MAX_BLOCK_GAS),
        "max_block_txs": int(MAX_BLOCK_TXS),
        "htlc_v1_enabled": _strict_bool('consensus.htlc_v1_enabled', _c.get('htlc_v1_enabled', _dc.get('htlc_v1_enabled', False))),
        "lottery_scale": _validate_lottery_value('lottery_scale', _c.get('lottery_scale', _dc.get('lottery_scale', 1 << 249)), 1),
        "attest_fresh_buffer": _validate_lottery_value('attest_fresh_buffer', _c.get('attest_fresh_buffer', _dc.get('attest_fresh_buffer', 5)), 0),
        "attest_growth_per_block": _validate_lottery_value('attest_growth_per_block', _c.get('attest_growth_per_block', _dc.get('attest_growth_per_block', 5)), 0),
        "slot_timeout": _validate_lottery_value('slot_timeout', _c.get('slot_timeout', _dc.get('slot_timeout', 30)), 1),
        "validators": _validators,
        "code": {"version": str(VERSION), "chain_id": int(CHAIN_ID)},
    }
    _rec.update(_fixed_consensus_params())
    return _rec


def _effective_consensus_ruleset() -> dict:
    """The ruleset this process actually runs: live module globals (which
    apply_consensus_config re-derives from the effective config at node
    init for the lottery keys; the rest are import-time CONFIG-derived and
    are what every validity/execution path reads). Fresh genesis files and
    all verification paths bind against this — never against a stale or
    hypothetical config. Fixed protocol literals merge from the same
    _fixed_consensus_params() source as the config-derived record."""
    _live = {
        "ruleset_version": GENESIS_CONSENSUS_RULESET_VERSION,
        "max_misses": int(MAX_MISSES),
        "ban_duration": int(BAN_DURATION),
        "prune_blocks": int(PRUNE_BLOCKS),
        "wall_density_3d": float(WALL_DENSITY_3D),
        "gas_price": int(GAS_PRICE),
        "gas_limit_default": int(GAS_LIMIT_DEFAULT),
        "max_bytecode": int(MAX_BYTECODE),
        "max_block_gas": int(MAX_BLOCK_GAS),
        "max_block_txs": int(MAX_BLOCK_TXS),
        "htlc_v1_enabled": bool(HTLC_V1_ENABLED),
        "lottery_scale": int(LOTTERY_SCALE),
        "attest_fresh_buffer": int(ATTEST_FRESH_BUFFER),
        "attest_growth_per_block": int(ATTEST_GROWTH_PER_BLOCK),
        "slot_timeout": int(SLOT_TIMEOUT),
        "validators": sorted(_effective_validators()),
        "code": {"version": str(VERSION), "chain_id": int(CHAIN_ID)},
    }
    _live.update(_fixed_consensus_params())
    return _live


def _normalize_svf_public(value) -> dict:
    """Normalise and validate a genesis svf_public field.

    Returns {"chain_id": int, "group_public_key": lowercase hex,
    "template_hashes": {name: lowercase sha256 hex}} with template names
    sorted. Raises ValueError on any missing or malformed field.
    """
    if not isinstance(value, dict):
        raise ValueError("malformed genesis field: svf_public must be an object")
    _cid = value.get("chain_id")
    if isinstance(_cid, bool) or not isinstance(_cid, int):
        raise ValueError("malformed genesis field: svf_public.chain_id must be an integer")
    _gpk = value.get("group_public_key")
    if not isinstance(_gpk, str):
        raise ValueError("malformed genesis field: svf_public.group_public_key must be a hex string")
    _gpk_norm = _gpk.strip().lower()
    if len(_gpk_norm) != 192:
        raise ValueError("malformed genesis field: svf_public.group_public_key must be 96 bytes (192 hex chars)")
    try:
        bytes.fromhex(_gpk_norm)
    except ValueError:
        raise ValueError("malformed genesis field: svf_public.group_public_key is not valid hex")
    _th = value.get("template_hashes")
    if not isinstance(_th, dict):
        raise ValueError("malformed genesis field: svf_public.template_hashes must be an object")
    _norm_th = {}
    for _name, _sha in _th.items():
        if not isinstance(_name, str) or not _name.strip():
            raise ValueError("malformed genesis field: svf_public.template_hashes keys must be non-empty strings")
        if not isinstance(_sha, str):
            raise ValueError("malformed genesis field: svf_public.template_hashes values must be hex strings")
        _sha_norm = _sha.strip().lower()
        if len(_sha_norm) != 64:
            raise ValueError("malformed genesis field: svf_public.template_hashes values must be 32 bytes (64 hex chars)")
        try:
            bytes.fromhex(_sha_norm)
        except ValueError:
            raise ValueError("malformed genesis field: svf_public.template_hashes values must be valid hex")
        _norm_th[_name] = _sha_norm
    return {
        "chain_id": int(_cid),
        "group_public_key": _gpk_norm,
        "template_hashes": {k: _norm_th[k] for k in sorted(_norm_th)},
    }


def _canonical_genesis_payload(data: dict) -> dict:
    """Build the exact dict covered by the genesis identity hash. Strict:
    every GENESIS_IDENTITY_FIELDS key must be present with a JSON-native
    shape (alloc/consensus dicts, miners/tx_hashes lists); transport keys
    (hash/signature/finalized) are dropped; anything else raises. Raises
    ValueError on any deviation — callers fail closed."""
    if not isinstance(data, dict):
        raise ValueError("genesis body is not a dict")
    _extra = [k for k in data if k not in GENESIS_IDENTITY_FIELDS
              and k not in GENESIS_TRANSPORT_KEYS]
    if _extra:
        raise ValueError("unknown genesis fields: " + ", ".join(sorted(map(str, _extra))))
    _missing = [k for k in GENESIS_IDENTITY_FIELDS if k not in data]
    if _missing:
        raise ValueError("missing genesis fields: " + ", ".join(_missing))
    try:
        _payload = {
            "id": int(data["id"]),
            "ts": data["ts"],
            "phash": str(data["phash"]),
            "miners": list(data["miners"]),
            "reward": int(data["reward"]),
            "tx_count": int(data["tx_count"]),
            "merkle_root": str(data["merkle_root"]),
            "nonce": int(data["nonce"]),
            "difficulty": int(data["difficulty"]),
            "version": str(data["version"]),
            "challenge": str(data["challenge"]),
            "coverage": data["coverage"],
            "total_tx_value": int(data["total_tx_value"]),
            "total_fees": int(data["total_fees"]),
            "tx_hashes": list(data["tx_hashes"]),
            "state_root": str(data["state_root"]),
            "producer_pub": str(data["producer_pub"]),
            "alloc": dict(data["alloc"]),
            "total_minted": int(data["total_minted"]),
            "chain_id": int(data["chain_id"]),
            "consensus": dict(data["consensus"]),
            "validators": list(data["validators"]),
        }
    except (TypeError, ValueError) as e:
        raise ValueError(f"malformed genesis field: {e}")
    if not isinstance(_payload["ts"], (int, float)) or isinstance(_payload["ts"], bool):
        raise ValueError("malformed genesis field: ts must be a number")
    if not isinstance(_payload["coverage"], (int, float)) or isinstance(_payload["coverage"], bool):
        raise ValueError("malformed genesis field: coverage must be a number")
    if not isinstance(data["alloc"], dict) or not isinstance(data["consensus"], dict):
        raise ValueError("malformed genesis field: alloc/consensus must be maps")
    if not isinstance(data["validators"], list) or any(not isinstance(v, str) for v in data["validators"]):
        raise ValueError("malformed genesis field: validators must be a list of strings")
    _payload["svf_public"] = _normalize_svf_public(data["svf_public"])
    return _payload


def _genesis_identity_hash(payload: dict) -> str:
    return hashlib.sha256(canonical_json_bytes(payload)).hexdigest()


def _genesis_export_verified_impl(body):
    """GENESIS-1 (Fix 1 + Fix 2): verify a genesis export — local file or
    peer-learned — against ONE canonical identity before any trust.

    Layer 1 (integrity): the strict canonical payload (header fields +
    alloc + total_minted + chain_id + full consensus record) re-hashed
    must equal the declared hash. ANY committed-field tampering — balances,
    supply, ruleset values, timestamps, roots — fails here, including files
    whose hash was honestly computed over the legacy 16-field shape (their
    recomputed hash differs: refused, see R9_MIGRATION_NOTES.md, no
    grandfathering).
    Layer 2 (policy): R9 economics (exact alloc sum == total_minted <=
    MAX_SUPPLY, canonical addrs/ints, state_root match).
    Layer 3 (compatibility): the file's consensus record must equal this
    process's effective ruleset — mixed-rule nodes refuse each other with
    the differing key named. Key order/whitespace variants verify
    identically (canonical JSON). Returns (ok, reason)."""

    if not isinstance(body, dict):
        return False, "genesis body is not a dict"
    try:
        if int(body.get("id", -1)) != 0:
            return False, "genesis id must be 0"
    except Exception:
        return False, "invalid genesis id"
    if str(body.get("version", "")) != str(VERSION):
        return False, "genesis version mismatch"
    try:
        if int(body.get("chain_id", -1)) != int(CHAIN_ID):
            return False, "chain_id mismatch"
    except Exception:
        return False, "invalid chain_id"
    if str(body.get("phash", "")) != "0" * 64:
        return False, "genesis phash must be all zeros"
    gh = str(body.get("hash", "")).lower()
    if len(gh) != 64 or not all(c in "0123456789abcdef" for c in gh):
        return False, "invalid genesis hash format"
    try:
        _payload = _canonical_genesis_payload(body)
    except ValueError as e:
        return False, str(e)
    try:
        _recomputed = _genesis_identity_hash(_payload)
    except Exception as e:
        return False, f"hash recomputation failed: {e}"
    if _recomputed != gh:
        return False, "recomputed genesis identity hash does not match declared hash"
    ok, why = _genesis_economics_ok(body)
    if not ok:
        return False, why
    # the top-level validator list and the consensus record must
    # (crafted or mixed-version) is refused here, never silently half-bound.
    try:
        _v_top = _normalize_validator_list(body.get("validators"))
        _v_rec_raw = body.get("consensus", {}).get("validators", None)
        _v_rec = _normalize_validator_list(
            _v_rec_raw if isinstance(_v_rec_raw, (list, tuple)) else [])
        if _v_top != _v_rec:
            return False, ("genesis validators list disagrees with consensus "
                           "record")
    except Exception as e:
        return False, f"validators comparison failed: {e}"
    try:
        _want = _effective_consensus_ruleset()
        _got = body.get("consensus")
        if not isinstance(_got, dict):
            return False, "genesis consensus record missing or not a map"
        def _norm(d):
            return json.loads(json.dumps(d, sort_keys=True, allow_nan=False))
        try:
            _nw, _ng = _norm(_want), _norm(_got)
        except (TypeError, ValueError) as _je:
            return False, f"consensus record not JSON-stable: {_je}"
        # B1: prune_blocks is a LOCAL retention policy, not a consensus
        # parameter. B1's principle is that pruning never changes whether a
        # block is valid, so two nodes with different prune windows must be
        # consensus key must still match exactly. Note: prune_blocks also
        _nw_cmp = {k: v for k, v in _nw.items() if k != "prune_blocks"}
        _ng_cmp = {k: v for k, v in _ng.items() if k != "prune_blocks"}
        if _ng_cmp != _nw_cmp:
            for _k in sorted(set(_nw_cmp) | set(_ng_cmp)):
                if _nw_cmp.get(_k) != _ng_cmp.get(_k):
                    return False, (f"genesis consensus ruleset differs from local "
                                   f"effective config at '{_k}': genesis={_ng_cmp.get(_k)!r} local={_nw_cmp.get(_k)!r}")
            return False, "genesis consensus ruleset shape differs from local effective config"
    except Exception as e:
        return False, f"consensus record comparison failed: {e}"
    return True, "ok"


def genesis_export_verified(body):
    """GENESIS-TOTAL-1: the single authoritative genesis verifier, as a TOTAL
    function. The inner implementation int()/float()-coerces attacker-
    controlled JSON (Python's parser accepts Infinity/NaN/huge numbers), and
    e.g. {"total_minted": Infinity} raised OverflowError out of
    _canonical_genesis_payload — an uncaught exception on a path fed by peer
    handshakes and local files instead of a clean rejection. Any exception is
    now a fail-closed (False, reason); a genesis is accepted ONLY if the
    implementation returns (True, ...) without raising."""
    try:
        return _genesis_export_verified_impl(body)
    except RecursionError:
        return False, "malformed genesis (nesting too deep)"
    except Exception as _e:
        return False, f"malformed genesis ({type(_e).__name__})"


def strict_replayed_sizes(entries, eligible_rows) -> Tuple[Dict[str, int], Optional[str]]:
    """LOTTERY-1: validate a block's declared lottery entries against this
    node's own eligible set.

    The old verifier trusted declared entries verbatim, so a producer could
    claim arbitrary weight for its own miner (and foreign producers slipped
    through a leniency branch). Rows are keyed by BOTH maze_id and minerid
    (the minermazes table carries both; legacy code keyed maze_id while
    entries use minerid — minerid wins when both are present).

    Returns (sizes, error_reason); error_reason is None on success."""
    local: Dict[str, int] = {}
    for r in eligible_rows or []:
        try:
            size = int(r["size"])
        except Exception:
            continue
        for k in ("maze_id", "minerid"):
            mid = None
            try:
                mid = r[k]
            except Exception:
                mid = r.get(k) if isinstance(r, dict) else None
            if mid:
                local[str(mid)] = size
    sizes: Dict[str, int] = {}
    for e in entries or []:
        mid = e.get("minerid")
        if not mid:
            return {}, "entry missing minerid"
        if str(mid) not in local:
            return {}, f"declared entry for unknown miner {str(mid)[:16]}"
        try:
            claimed = int(e.get("mazesize", 0))
        except (TypeError, ValueError):
            return {}, f"invalid mazesize for {str(mid)[:16]}"
        if claimed != local[str(mid)]:
            return {}, (f"mazesize mismatch for {str(mid)[:16]}: "
                        f"declared {claimed}, local {local[str(mid)]}")
        sizes[str(mid)] = claimed
    return sizes, None

# --- Consensus RNG (hash-based deterministic random stream) --
class ConsensusRng:
    """Deterministic hash-based random stream for consensus. Never use Python random."""
    def __init__(self, seed: bytes):
        self.seed = seed
        self.counter = 0

    def bytes(self, length: int) -> bytes:
        output = bytearray()
        while len(output) < length:
            output.extend(eth_keccak(
                b"MCXPOGRNGV1"
                + self.seed
                + self.counter.to_bytes(8, "big")
            ))
            self.counter += 1
        return bytes(output[:length])

    def randbelow(self, upper: int) -> int:
        if upper <= 0:
            raise ValueError("upper must be positive")
        limit = (1 << 256) - ((1 << 256) % upper)
        while True:
            value = int.from_bytes(self.bytes(32), "big")
            if value < limit:
                return value % upper

def canonical_json_bytes(value: Any) -> bytes:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    ).encode("utf-8")

def block_signing_payload(block: dict) -> bytes:
    unsigned = {
        key: value
        for key, value in block.items()
        if key not in CONSENSUS_EXCLUDED_FIELDS
    }
    return canonical_json_bytes(unsigned)

def calculate_block_hash(block: dict) -> str:
    return hashlib.sha256(block_signing_payload(block)).hexdigest()

def sign_bytes(priv_hex: str, message: bytes) -> str:
    priv_int = int(priv_hex, 16)
    priv_key = ec.derive_private_key(priv_int, ec.SECP256K1())
    sig = priv_key.sign(message, ec.ECDSA(hashes.SHA256()))
    r, s = decode_dss_signature(sig)
    if s > SECP256K1_N // 2:
        s = SECP256K1_N - s
    return f"{r:064x}{s:064x}"

def verify_signature_bytes(pub_hex: str, message: bytes, sig_hex: str) -> bool:
    if not isinstance(sig_hex, str) or not re.fullmatch(r"[0-9a-fA-F]{128}", sig_hex):
        return False
    if not isinstance(pub_hex, str) or not re.fullmatch(r"04[0-9a-fA-F]{128}", pub_hex):
        return False
    try:
        if len(pub_hex) != 130 or not pub_hex.startswith("04"):
            return False
        x = int(pub_hex[2:66], 16)
        y = int(pub_hex[66:], 16)
        pub_nums = ec.EllipticCurvePublicNumbers(x, y, ec.SECP256K1())
        pub = pub_nums.public_key()
        r = int(sig_hex[:64], 16)
        s = int(sig_hex[64:], 16)
        if s > SECP256K1_N // 2:
            return False
        pub.verify(encode_dss_signature(r, s), message, ec.ECDSA(hashes.SHA256()))
        return True
    except Exception:
        return False

def seal_block(block: dict, private_key: str) -> dict:
    sealed = dict(block)
    sealed["hash"] = calculate_block_hash(sealed)
    sealed["signature"] = sign_bytes(private_key, bytes.fromhex(sealed["hash"]))
    return sealed

def sign_message(priv_hex, message):
    if isinstance(message, str):
        message = message.encode("utf-8")
    return sign_bytes(priv_hex, message)

def verify_signature(pub_hex, message, sig_hex):
    if isinstance(message, str):
        message = message.encode("utf-8")
    return verify_signature_bytes(pub_hex, message, sig_hex)

# including genesis (height 0). A block's timestamp T must satisfy
BLOCK_TIME_WINDOW_MAX = 7200
MEDIAN_WINDOW_BLOCKS = 11


def _median_ancestor_timestamp(ancestor_ts: list) -> float:
    """Median of the given ancestor timestamps (sorted, middle element).
    Pure arithmetic: no clock, no datetime. Empty input -> 0.0."""
    vals = sorted(float(t) for t in (ancestor_ts or []) if isinstance(t, (int, float)))
    if not vals:
        return 0.0
    n = len(vals)
    if n % 2 == 1:
        return vals[n // 2]
    return (vals[n // 2 - 1] + vals[n // 2]) / 2.0


def _block_timestamp_ok(block_ts, ancestor_ts, is_genesis=False) -> bool:
    """O2: M < T <= M + 7200, where M is the median of the up to 11 most
    recent ancestors' timestamps including genesis. Pure arithmetic over
    chain data only — the verifier never reads a clock. A genesis block
    (height 0) is not checked. OverflowError from a peer-supplied
    arbitrary-precision JSON integer is a plain False (rejection), not an
    exception."""
    if is_genesis:
        return True
    try:
        T = float(block_ts)
    except (TypeError, ValueError, OverflowError):
        return False
    M = _median_ancestor_timestamp(ancestor_ts)
    if M <= 0:
        return False
    return M < T <= M + BLOCK_TIME_WINDOW_MAX


def _clamp_producer_timestamp(now_ts, ancestor_ts) -> float:
    """O2 producer stamp rule: T = clamp(now, M + 1, M + 7200).
    The producer's wall clock is used HERE only, never by the verifier."""
    M = _median_ancestor_timestamp(ancestor_ts)
    if M <= 0:
        M = float(now_ts)
    lo = M + 1.0
    hi = M + BLOCK_TIME_WINDOW_MAX
    return max(lo, min(float(now_ts), hi))


def _chain_time_drift_seconds(chain_time, local_clock) -> float:
    """Operator-only drift magnitude. NO consensus effect; the verifier
    never calls this."""
    return abs(float(chain_time) - float(local_clock))


_MAZE_STATE_COLUMNS = ("maze_id", "minerid", "walldensityppm", "seed",
                       "goalx", "goaly", "goalz")


def _maze_state_entry_from_row(row: dict) -> dict:
    """One chain-carried maze fact set, shaped from a maze row.
    Keys match _MAZE_STATE_COLUMNS exactly."""
    return {
        "maze_id": str(row.get("maze_id") or ""),
        "minerid": str(row.get("minerid") or ""),
        "walldensityppm": int(row.get("walldensityppm") or 0),
        "seed": str(row.get("seed") or ""),
        "goalx": int(row.get("goalx") or 0),
        "goaly": int(row.get("goaly") or 0),
        "goalz": int(row.get("goalz") or 0),
    }


def _build_maze_state(maze_rows: list, maze_attestation) -> list:
    """O5 producer side: the committed maze facts this block establishes.

    Every maze whose committed facts the block's state root depends on is
    carried here, so a follower rebuilds the maze section from the chain
    alone. The attesting maze must be present; its maze_id is the pubkey,
    which verify_block_proof already checks against the attestation.

    Pure function of the rows plus the block's own attestation: no clock,
    no gossip, no host-local state.
    """
    if not isinstance(maze_attestation, dict) or not maze_attestation:
        return []
    att_mid = str(maze_attestation.get("maze_id", "") or "").lower()
    out, seen = [], set()
    for _row in (maze_rows or []):
        if not isinstance(_row, dict):
            continue
        _mid = str(_row.get("maze_id") or "")
        if not _mid or _mid.lower() in seen:
            continue
        seen.add(_mid.lower())
        out.append(_maze_state_entry_from_row(_row))
    # The attested maze must be carried even if it has no local row yet.
    if att_mid and att_mid not in seen:
        out.append(_maze_state_entry_from_row({
            "maze_id": maze_attestation.get("maze_id", ""),
            "minerid": str(maze_attestation.get("minerid", "") or ""),
        }))
    return out


def hash_block(b):
    return calculate_block_hash(b)

def hash_tx(tx):
    return hashlib.sha256(canonical_json_bytes(tx)).hexdigest()

VERIFY_STATE_ROOT = True
STATE_COMMITMENT_SCOPE = "two-key"

def _topic_to_int(t):
    try:
        if isinstance(t, int):
            return t
        s = str(t).strip()
        return int(s, 16) if s.lower().startswith("0x") else int(s)
    except (TypeError, ValueError):
        return None


def _log_matches_filter(log_address, log_topics, addresses, topics) -> bool:
    # : eth filter semantics against ONE log (never the
    # a longer filter than the log's topics never matches.
    try:
        if addresses is not None:
            want = [addresses] if isinstance(addresses, str) else list(addresses)
            if str(log_address or "").lower() not in [str(a or "").lower() for a in want]:
                return False
        if topics:
            lt = []
            for _t in (log_topics or []):
                _ti = _topic_to_int(_t)
                if _ti is None:
                    return False
                lt.append(_ti)
            for _i, _f in enumerate(topics):
                if _f is None:
                    continue
                _want = _f if isinstance(_f, list) else [_f]
                _wi = []
                for _x in _want:
                    _xi = _topic_to_int(_x)
                    if _xi is None:
                        return False
                    _wi.append(_xi)
                if _i >= len(lt) or lt[_i] not in _wi:
                    return False
    except Exception:
        return False
    return True


def _enrich_eth_log(log, block_hash, block_number, tx_hash, tx_index, log_index) -> dict:
    try:
        _topics = []
        for _t in (log.get("topics") or []):
            _ti = _topic_to_int(_t)
            _topics.append("0x" + (int(_ti).to_bytes(32, "big").hex() if _ti is not None else "00" * 32))
    except Exception:
        _topics = []
    _data = log.get("data", "")
    _data = _data if isinstance(_data, str) and _data.startswith("0x") else "0x" + (str(_data) if isinstance(_data, str) else "")
    return {"address": log.get("address", ""), "topics": _topics, "data": _data,
            "blockHash": block_hash, "blockNumber": block_number,
            "transactionHash": tx_hash, "transactionIndex": tx_index,
            "logIndex": hex(log_index), "removed": False}


def _eth_sig_fields(tx: dict):
    try:
        sig = tx.get('signature', '')
        if isinstance(sig, str) and (sig.startswith('0x') or len(sig) > 130):
            decoded = decode_raw_eth_transaction(sig)
            v = int(decoded.get('v', 0) or 0)
            r = int(decoded.get('r', 0) or 0)
            s = int(decoded.get('s', 0) or 0)
            if v and r and s:
                return hex(v), hex(r), hex(s)
    except Exception:
        pass
    return None, None, None


def _logs_bloom(logs) -> str:
    try:
        arr = bytearray(256)
        items = []
        for log in (logs or []):
            if not isinstance(log, dict):
                continue
            try:
                items.append(bytes.fromhex(str(log.get('address', '')).removeprefix('0x')))
            except (ValueError, AttributeError):
                pass
            for _t in (log.get('topics') or []):
                try:
                    _ti = _topic_to_int(_t)
                    if _ti is None:
                        continue
                    items.append(int(_ti).to_bytes(32, 'big'))
                except Exception:
                    continue
        for _x in items:
            try:
                _h = eth_keccak(bytes(_x))
            except Exception:
                continue
            for _k in range(3):
                _pos = (_h[2 * _k] * 256 + _h[2 * _k + 1]) & 2047
                arr[255 - (_pos >> 3)] |= (1 << (_pos & 7))
        return "0x" + bytes(arr).hex()
    except Exception:
        return "0x" + "00" * 256


def _cumulative_gas_used(ordered_pairs, tx_hash) -> int:
    try:
        _total = 0
        for _h, _g in ordered_pairs:
            _total += int(_g or 0)
            if _h == tx_hash:
                return _total
    except Exception:
        pass
    return 0


async def _block_gas_used(db, block_id: int) -> int:
    try:
        if db.db_type == "sqlite":
            _row = await db.fetchrow(
                "SELECT COALESCE(SUM(gas_used),0) AS s FROM transaction_receipts WHERE block_id = ?",
                block_id)
        else:
            _row = await db.fetchrow(
                "SELECT COALESCE(SUM(gas_used),0) AS s FROM transaction_receipts WHERE block_id = $1",
                block_id)
        return int((_row['s'] if _row else 0) or 0)
    except Exception:
        return 0


def _tx_lists_consistent(tx_hashes, tx_list):
    # (I-): the committed tx_hashes sequence must EXACTLY
    try:
        if not isinstance(tx_hashes, list) or not isinstance(tx_list, list):
            return False, "not lists"
        if len(tx_hashes) != len(tx_list):
            return False, "length mismatch"
        for _h, _t in zip(tx_hashes, tx_list):
            if not isinstance(_t, dict) or _t.get("tx_hash") != _h:
                return False, "ordered hash mismatch"
    except Exception:
        return False, "uncomparable"
    return True, ""


def compute_merkle_root(tx_hashes: list) -> str:
    if not tx_hashes:
        return "0" * 64
    level = [
        bytes.fromhex(h[2:] if isinstance(h, str) and h[:2].lower() == "0x" else h)
        for h in tx_hashes
    ]
    while len(level) > 1:
        carry = level.pop() if len(level) % 2 == 1 else None
        level = [eth_keccak(level[i] + level[i + 1]) for i in range(0, len(level), 2)]
        if carry is not None:
            level.append(carry)
    return level[0].hex()


def _s256(x: int) -> int:
    """Interpret a 256-bit word as two's-complement signed (EVM-OPS)."""
    return x - (1 << 256) if x >= (1 << 255) else x

_WALLET_HEX = frozenset("0123456789abcdefABCDEF")

def _valid_wallet(addr) -> bool:
    """A wallet is '0x' followed by at least 40 hex digits. Empty, non-string
    and malformed values are rejected, so a transfer can never credit an
    unnamed account (TRANSFER-VALID-1)."""
    if not isinstance(addr, str) or not addr.startswith("0x"):
        return False
    body = addr[2:]
    return len(body) >= 40 and all(c in _WALLET_HEX for c in body)

SVF_ACTIVATION_HEIGHT = 0
_DB_FAILED = object()
SVP_VERSION = 1
SVP_MODES = ("standard_l1", "spatial_per_transfer", "spatial_batch", "hybrid")
SVP_FAMILIES = ("none", "path_length_band", "turn_count_band")
SVP_FIELDS = ("batch_max", "difficulty_max", "difficulty_min", "evidence_threshold",
              "family", "fallback", "min_distinct_miners", "mode", "version", "window_blocks")
SVP_CAPS = {"difficulty": (1, 8), "evidence_threshold": (1, 16),
            "min_distinct_miners": (1, 16), "window_blocks": (1, 200), "batch_max": (1, 1000)}
SVP_HASH_DOMAIN = b"MCX-SVP-v1"
SVF_COMMIT_DOMAIN = b"MCX-SVF-COMMIT-v1"


class SVPError(ValueError):
    """Raised for any profile or commitment input that must fail closed."""


def _svp_reject_duplicate_keys(pairs):
    out = {}
    for k, v in pairs:
        if k in out:
            raise SVPError(f"duplicate field: {k}")
        out[k] = v
    return out


def _svp_reject_float(_text):
    raise SVPError("floats are not allowed in a profile")


def _svp_reject_constant(_text):
    raise SVPError(f"non-finite constant not allowed: {_text}")


def _svp_int(name, value, lo, hi):
    if isinstance(value, bool) or not isinstance(value, int):
        raise SVPError(f"{name} must be an integer")
    if not (lo <= value <= hi):
        raise SVPError(f"{name} out of range [{lo}, {hi}]: {value}")
    return value


def svp_canonical_bytes(profile: dict) -> bytes:
    """The one canonical serialization: sorted keys, no whitespace, ASCII."""
    return json.dumps(profile, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=True, allow_nan=False).encode("ascii")


def svp_validate(profile: dict) -> dict:
    """Validate an already-decoded profile. Returns a copy. Raises SVPError."""
    if not isinstance(profile, dict):
        raise SVPError("profile must be a JSON object")
    if set(profile.keys()) != set(SVP_FIELDS):
        missing = sorted(set(SVP_FIELDS) - set(profile))
        extra = sorted(set(profile) - set(SVP_FIELDS))
        raise SVPError(f"fields must be exactly {list(SVP_FIELDS)}; missing={missing} extra={extra}")
    if isinstance(profile["version"], bool) or profile["version"] != SVP_VERSION:
        raise SVPError(f"unsupported profile version: {profile['version']!r}")
    mode = profile["mode"]
    family = profile["family"]
    if mode not in SVP_MODES:
        raise SVPError(f"unknown mode: {mode!r}")
    if family not in SVP_FAMILIES:
        raise SVPError(f"unknown family: {family!r}")
    if profile["fallback"] != "standard_l1":
        raise SVPError("fallback must be standard_l1: a profile can never remove the L1 path")
    dmin = _svp_int("difficulty_min", profile["difficulty_min"], *SVP_CAPS["difficulty"])
    dmax = _svp_int("difficulty_max", profile["difficulty_max"], *SVP_CAPS["difficulty"])
    if dmin > dmax:
        raise SVPError("difficulty_min must not exceed difficulty_max")
    ev = _svp_int("evidence_threshold", profile["evidence_threshold"], *SVP_CAPS["evidence_threshold"])
    md = _svp_int("min_distinct_miners", profile["min_distinct_miners"], *SVP_CAPS["min_distinct_miners"])
    if md > ev:
        raise SVPError("min_distinct_miners must not exceed evidence_threshold")
    _svp_int("window_blocks", profile["window_blocks"], *SVP_CAPS["window_blocks"])
    bm = _svp_int("batch_max", profile["batch_max"], *SVP_CAPS["batch_max"])
    if mode == "standard_l1":
        if family != "none" or (dmin, dmax, ev, md, bm) != (1, 1, 1, 1, 1):
            raise SVPError("standard_l1 takes no challenge: family none, all challenge fields at minimum")
    elif mode == "spatial_per_transfer":
        if family == "none":
            raise SVPError("spatial modes need a challenge family")
        if bm != 1:
            raise SVPError("spatial_per_transfer must have batch_max 1")
    else:
        if family == "none":
            raise SVPError("spatial modes need a challenge family")
        if bm < 2:
            raise SVPError(f"{mode} must have batch_max of at least 2")
    return dict(profile)


def svp_parse(raw: bytes) -> dict:
    """Strict parse. The raw bytes must equal the canonical serialization."""
    if not isinstance(raw, (bytes, bytearray)):
        raise SVPError("profile must be bytes")
    try:
        text = bytes(raw).decode("ascii")
        obj = json.loads(text, object_pairs_hook=_svp_reject_duplicate_keys,
                         parse_float=_svp_reject_float, parse_constant=_svp_reject_constant)
    except (UnicodeDecodeError, ValueError) as exc:
        raise SVPError(f"malformed profile: {exc}") from None
    profile = svp_validate(obj)
    if svp_canonical_bytes(profile) != bytes(raw):
        raise SVPError("profile is not in canonical form")
    return profile


def svp_hash(profile: dict) -> bytes:
    """32-byte profile hash over the canonical bytes, domain separated."""
    return hashlib.sha256(SVP_HASH_DOMAIN + svp_canonical_bytes(svp_validate(profile))).digest()


def svf_commitment(chain_id: int, token_address: str, profile_hash: bytes,
                   batch_id: int, window_start: int, nonce: int) -> bytes:
    """Binding commitment for one validation instance. It binds the chain,
    token, profile, batch, window and a sequence nonce, so it cannot be
    replayed across chains, tokens, profiles or batches. It is NOT a challenge
    seed: the unpredictable seed is an open design item."""
    if not _valid_wallet(token_address):
        raise SVPError("invalid token address")
    if not isinstance(profile_hash, (bytes, bytearray)) or len(profile_hash) != 32:
        raise SVPError("profile_hash must be 32 bytes")
    for name, value in (("chain_id", chain_id), ("batch_id", batch_id),
                        ("window_start", window_start), ("nonce", nonce)):
        if isinstance(value, bool) or not isinstance(value, int) or not (0 <= value < 2 ** 64):
            raise SVPError(f"{name} must be an unsigned 64-bit integer")
    token = token_address.lower().encode("ascii")
    h = hashlib.sha256()
    h.update(SVF_COMMIT_DOMAIN)
    h.update(struct.pack(">Q", chain_id))
    h.update(struct.pack(">H", len(token)))
    h.update(token)
    h.update(bytes(profile_hash))
    h.update(struct.pack(">QQQ", batch_id, window_start, nonce))
    return h.digest()


def svf_active_at(height: int) -> bool:
    """SVF is always on (R1): True for every height >= SVF_ACTIVATION_HEIGHT (0)."""
    return SVF_ACTIVATION_HEIGHT is not None and int(height) >= SVF_ACTIVATION_HEIGHT


def _svf_selector(signature: str) -> bytes:
    """4-byte EVM function selector from a function signature."""
    return eth_keccak(signature.encode("ascii"))[:4]

SVF_DOMAIN_INTENT = b"MCX-SVF-INTENT-v1"
SVF_DOMAIN_BATCH_LEAF = b"MCX-SVF-BATCH-LEAF-v1"
SVF_DOMAIN_BATCH_NODE = b"MCX-SVF-BATCH-NODE-v1"
SVF_DOMAIN_CHALLENGE = b"MCX-SVF-CHALLENGE-v1"
SVF_DOMAIN_EVIDENCE = b"MCX-SVF-EVIDENCE-v1"
SVF_BILLABLE_SIG_BYTES = 65
SVF_FEE_PER_BYTE = 1
SVF_MAX_BATCH_INTENTS = 1000
SVF_MAX_EVIDENCE_RECORDS = 512
SVF_MAX_WINDOW_BLOCKS = 200
SVF_MAX_AMOUNT = 2 ** 63 - 1
SVF_DIRECTIONS = ("east", "west", "north", "south", "up", "down")
SVF_INTENT_FIELDS = ("chain_id", "token", "sender", "recipient", "amount", "nonce",
                     "profile_hash", "valid_after_height", "valid_before_height")
SVF_EVIDENCE_FIELDS = ("chain_id", "miner", "maze_id", "maze_version", "move_nonce",
                       "direction", "prev_hash", "parent_height")
SVF_STATES = ("RECEIVED", "RESERVED", "EVIDENCE_OPEN", "EVIDENCE_FROZEN",
              "VALIDATED", "SETTLED", "REJECTED", "EXPIRED")
SVF_TRANSITIONS = {
    "RECEIVED": {"RESERVED", "REJECTED"},
    "RESERVED": {"EVIDENCE_OPEN", "EXPIRED"},
    "EVIDENCE_OPEN": {"EVIDENCE_FROZEN", "EXPIRED"},
    "EVIDENCE_FROZEN": {"VALIDATED", "REJECTED", "EXPIRED"},
    "VALIDATED": {"SETTLED", "EXPIRED"},
    "SETTLED": set(), "REJECTED": set(), "EXPIRED": set(),
}
SVF_RELEASING_STATES = {"REJECTED", "EXPIRED"}


class SVFBlocked(RuntimeError):
    """A required prerequisite (B1 beacon, B2 evidence) is unavailable."""


class SVFReject(ValueError):
    """Input or transition violates the SVF rules; always fail closed."""


def _svf_canon(obj) -> bytes:
    return json.dumps(obj, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=True, allow_nan=False).encode("ascii")


def _svf_int(name, value, lo, hi):
    if isinstance(value, bool) or not isinstance(value, int):
        raise SVFReject(f"{name} must be an integer")
    if not (lo <= value <= hi):
        raise SVFReject(f"{name} out of range [{lo}, {hi}]")
    return value


def _svf_hex32(name, value) -> str:
    if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
        raise SVFReject(f"{name} must be 64 lowercase hex characters")
    return value


def svf_intent_body(intent: dict, expected_chain_id: int) -> dict:
    """Canonical signed intent body. Exact key set; no fee field (fee is derived)."""
    if not isinstance(intent, dict) or set(intent.keys()) != set(SVF_INTENT_FIELDS):
        raise SVFReject(f"intent fields must be exactly {list(SVF_INTENT_FIELDS)}")
    chain_id = _svf_int("chain_id", intent["chain_id"], 0, 2 ** 63 - 1)
    if chain_id != int(expected_chain_id):
        raise SVFReject("chain_id mismatch (domain separation)")
    for name in ("token", "sender", "recipient"):
        if not _valid_wallet(intent[name]):
            raise SVFReject(f"{name} is not a valid wallet")
    if intent["sender"].lower() == intent["recipient"].lower():
        raise SVFReject("self-transfer not allowed")
    amount = _svf_int("amount", intent["amount"], 1, SVF_MAX_AMOUNT)
    nonce = _svf_int("nonce", intent["nonce"], 0, 2 ** 63 - 1)
    profile_hash = _svf_hex32("profile_hash", intent["profile_hash"])
    after = _svf_int("valid_after_height", intent["valid_after_height"], 0, 2 ** 63 - 1)
    before = _svf_int("valid_before_height", intent["valid_before_height"], 1, 2 ** 63 - 1)
    if before <= after:
        raise SVFReject("valid_before_height must exceed valid_after_height")
    return {
        "chain_id": chain_id, "token": intent["token"].lower(), "sender": intent["sender"].lower(),
        "recipient": intent["recipient"].lower(), "amount": amount, "nonce": nonce,
        "profile_hash": profile_hash, "valid_after_height": after, "valid_before_height": before,
    }


def svf_billable_bytes(body: dict) -> int:
    """Canonical billable bytes: canonical JSON of the body plus the fixed signature cost."""
    return len(_svf_canon(body)) + SVF_BILLABLE_SIG_BYTES


def svf_fee(body: dict) -> int:
    """Required MCX fee (subunits): canonical billable bytes x 1. No SVF floor or ceiling."""
    fee = svf_billable_bytes(body) * SVF_FEE_PER_BYTE
    if fee <= 0:
        raise SVFReject("SVF fee must be positive")
    return fee


def svf_intent_hash(body: dict, fee: int) -> bytes:
    """Intent identity over the canonical body and the declared fee."""
    return hashlib.sha256(SVF_DOMAIN_INTENT + _svf_canon(dict(body, fee=int(fee)))).digest()


def svf_reserve_batch(state: dict, intents: list) -> tuple:
    """Deterministic reservation of a batch of intents.

    state = {"balances": {(token, wallet): int}, "reserved": {(token, wallet): int},
             "nonces": {(token, sender): int}, "open": {hash: (token, sender, amount)},
             "seen": set_of_hashes}
    intents = list of dicts with keys: order (tuple), hash (bytes), token, sender,
              amount, nonce, body.
    Processing order is sorted by (order, hash). An intent is accepted iff it is not a
    duplicate, its nonce equals the sender's next expected nonce, and the spendable
    balance (balance - reserved) covers it. Rejected intents reserve nothing.
    The input state is not mutated. Returns (new_state, results) with
    results = [(hash, "ACCEPTED" | reason)] in processing order.
    """
    st = {
        "balances": dict(state["balances"]),
        "reserved": dict(state["reserved"]),
        "nonces": dict(state["nonces"]),
        "open": dict(state["open"]),
        "seen": set(state["seen"]),
    }
    results = []
    for it in sorted(intents, key=lambda x: (x["order"], x["hash"])):
        h = it["hash"]
        key = (it["token"], it["sender"])
        if h in st["seen"]:
            results.append((h, "DUPLICATE"))
            continue
        expected = st["nonces"].get(key, 0)
        if it["nonce"] != expected:
            results.append((h, "BAD_NONCE"))
            continue
        try:
            amount = it["amount"]
            if isinstance(amount, bool) or not isinstance(amount, int) or amount < 1:
                results.append((h, "BAD_AMOUNT"))
                continue
        except (TypeError, KeyError):
            results.append((h, "BAD_AMOUNT"))
            continue
        spendable = st["balances"].get(key, 0) - st["reserved"].get(key, 0)
        if spendable < amount:
            results.append((h, "INSUFFICIENT_SPENDABLE"))
            continue
        st["seen"].add(h)
        st["reserved"][key] = st["reserved"].get(key, 0) + amount
        st["nonces"][key] = expected + 1
        st["open"][h] = (it["token"], it["sender"], amount)
        results.append((h, "ACCEPTED"))
    return st, results


def svf_release(state: dict, intent_hash: bytes) -> dict:
    """Release an open reservation. Releasing an unknown or already-released hash raises."""
    if intent_hash not in state["open"]:
        raise SVFReject("no open reservation for this intent (already released or never reserved)")
    token, sender, amount = state["open"][intent_hash]
    key = (token, sender)
    st = {
        "balances": dict(state["balances"]),
        "reserved": dict(state["reserved"]),
        "nonces": dict(state["nonces"]),
        "open": {k: v for k, v in state["open"].items() if k != intent_hash},
        "seen": set(state["seen"]),
    }
    st["reserved"][key] = st["reserved"].get(key, 0) - amount
    if st["reserved"][key] < 0:
        raise SVFReject("reserved balance would go negative")
    return st


def svf_next_state(current: str, nxt: str) -> str:
    """Lifecycle transition table. Illegal transitions raise."""
    if current not in SVF_TRANSITIONS or nxt not in SVF_STATES:
        raise SVFReject("unknown lifecycle state")
    if nxt not in SVF_TRANSITIONS[current]:
        raise SVFReject(f"illegal transition {current} -> {nxt}")
    return nxt


def svf_batch_root(intent_hashes: list) -> bytes:
    """Canonical Merkle root over sorted, unique intent hashes (odd node promoted)."""
    if len(intent_hashes) > SVF_MAX_BATCH_INTENTS:
        raise SVFReject("batch exceeds SVF_MAX_BATCH_INTENTS")
    if len(set(intent_hashes)) != len(intent_hashes):
        raise SVFReject("duplicate intent in batch")
    for i, h in enumerate(intent_hashes):
        if not isinstance(h, (bytes, bytearray)) or len(h) != 32:
            raise SVFReject(f"intent_hashes[{i}] must be exactly 32 bytes")
    if not intent_hashes:
        return hashlib.sha256(SVF_DOMAIN_BATCH_NODE + b"empty").digest()
    level = [hashlib.sha256(SVF_DOMAIN_BATCH_LEAF + bytes(h)).digest() for h in sorted(intent_hashes)]
    while len(level) > 1:
        nxt = []
        for i in range(0, len(level) - 1, 2):
            nxt.append(hashlib.sha256(SVF_DOMAIN_BATCH_NODE + level[i] + level[i + 1]).digest())
        if len(level) % 2 == 1:
            nxt.append(level[-1])
        level = nxt
    return level[0]


def svf_challenge(beacon, chain_id: int, token: str, profile_hash: str, batch_root: bytes,
                  window_start: int, window_end: int) -> bytes:
    """Challenge seed derivation. Requires a 32-byte beacon from the B1 design.
    Without one this raises SVFBlocked: no default or fallback seed exists."""
    if beacon is None:
        raise SVFBlocked("B1 randomness beacon unavailable: SVF activation is blocked")
    if not isinstance(beacon, (bytes, bytearray)) or len(beacon) != 32:
        raise SVFReject("beacon must be 32 bytes")
    _svf_int("chain_id", chain_id, 0, 2 ** 63 - 1)
    if not _valid_wallet(token):
        raise SVFReject("invalid token")
    _svf_hex32("profile_hash", profile_hash)
    if not isinstance(batch_root, (bytes, bytearray)) or len(batch_root) != 32:
        raise SVFReject("batch_root must be 32 bytes")
    _svf_int("window_start", window_start, 0, 2 ** 63 - 1)
    _svf_int("window_end", window_end, 1, 2 ** 63 - 1)
    span = window_end - window_start
    if not (1 <= span <= SVF_MAX_WINDOW_BLOCKS):
        raise SVFReject(f"evidence window must span 1..{SVF_MAX_WINDOW_BLOCKS} blocks")
    tok = token.lower().encode("ascii")
    h = hashlib.sha256()
    h.update(SVF_DOMAIN_CHALLENGE)
    h.update(struct.pack(">Q", chain_id))
    h.update(struct.pack(">H", len(tok)) + tok)
    h.update(bytes.fromhex(profile_hash))
    h.update(bytes(batch_root))
    h.update(struct.pack(">QQ", window_start, window_end))
    h.update(bytes(beacon))
    return h.digest()


def svf_evidence_body(rec: dict) -> dict:
    """Canonical evidence record body. A record is one authenticated move with its link to the
    previous record. The signature over this body is NOT produced by current miner software
    (see SVF_DESIGN.md, B2): this function only defines the format."""
    if not isinstance(rec, dict) or set(rec.keys()) != set(SVF_EVIDENCE_FIELDS):
        raise SVFReject(f"evidence fields must be exactly {list(SVF_EVIDENCE_FIELDS)}")
    if rec["direction"] not in SVF_DIRECTIONS:
        raise SVFReject("unknown direction")
    if not _valid_wallet(rec["miner"]):
        raise SVFReject("miner must be a wallet-format identity")
    prev = rec["prev_hash"]
    if prev != "00" * 32:
        _svf_hex32("prev_hash", prev)
    return {
        "chain_id": _svf_int("chain_id", rec["chain_id"], 0, 2 ** 63 - 1),
        "miner": rec["miner"].lower(),
        "maze_id": str(rec["maze_id"]),
        "maze_version": _svf_int("maze_version", rec["maze_version"], 0, 2 ** 63 - 1),
        "move_nonce": _svf_int("move_nonce", rec["move_nonce"], 0, 2 ** 63 - 1),
        "direction": rec["direction"],
        "prev_hash": prev,
        "parent_height": _svf_int("parent_height", rec["parent_height"], 0, 2 ** 63 - 1),
    }


def svf_evidence_hash(body: dict) -> bytes:
    return hashlib.sha256(SVF_DOMAIN_EVIDENCE + _svf_canon(body)).digest()


def svf_verify_evidence_chain(records: list, verify_sig) -> dict:
    """Strict verification of an ordered evidence chain for ONE miner and ONE maze version.

    Rules: 1..SVF_MAX_EVIDENCE_RECORDS records; same miner, maze, maze_version and chain_id;
    move_nonce contiguous from the first record; each prev_hash equals the previous record's
    hash (first record links to 00..00); every record's signature verifies with verify_sig(
    miner, body_bytes, signature) -> bool. A window that spans a maze growth (maze_version
    change) is rejected, so the verdict never has to reason about two versions at once.
    Returns {"count", "tip_hash"} or raises SVFReject.
    """
    if not isinstance(records, list) or not (1 <= len(records) <= SVF_MAX_EVIDENCE_RECORDS):
        raise SVFReject(f"evidence must contain 1..{SVF_MAX_EVIDENCE_RECORDS} records")
    prev_h = "00" * 32
    first = None
    expect_nonce = None
    for entry in records:
        if not isinstance(entry, dict) or set(entry.keys()) != {"body", "signature"}:
            raise SVFReject("each record must carry exactly a body and a signature")
        body = svf_evidence_body(entry["body"])
        if first is None:
            first = body
            expect_nonce = body["move_nonce"]
        for k in ("chain_id", "miner", "maze_id", "maze_version"):
            if body[k] != first[k]:
                raise SVFReject(f"record {k} differs within the window")
        if body["move_nonce"] != expect_nonce:
            raise SVFReject("move_nonce is not contiguous (gap, duplicate or reorder)")
        if body["prev_hash"] != prev_h:
            raise SVFReject("prev_hash does not link to the previous record")
        if not isinstance(entry["signature"], str) or not verify_sig(body["miner"], _svf_canon(body), entry["signature"]):
            raise SVFReject("record signature does not verify")
        prev_h = svf_evidence_hash(body).hex()
        expect_nonce += 1
    return {"count": len(records), "tip_hash": prev_h}

