SVF_COMMITTEE_THRESHOLD = 3
SVF_COMMITTEE_EPOCH = 0

# memory only and is never logged (R5).
SVF_GROUP_PUBLIC_KEY = None
SVF_APPROVED_TEMPLATES = {}
# Testnet template approved by an auto-generated test key (see
# _svf_auto_generate_test_key). The sha256 is the hash of the standard
# test-token forwarder runtime (the direct_erc20 template); it is a public
# value, already present in every testnet genesis. Used ONLY for a
# node-generated testnet key on chain 6621 — never for mainnet.
_SVF_TESTNET_TEMPLATE_HASHES = [
    {"name": "direct_erc20",
     "sha256": "42ef31de0b91480beda1431b9e447a39c086d343ef6d69d206d94bb71e450437",
     "audit_ref": "testnet tooling: forwarder contract calling SVF guard 0x0800 (no audit)"},
]
SVF_KEY_IS_TEST = None
SVF_KEY_CHAIN_ID = None
SVF_KEY_FILE = None
SVF_KEY_DKG = None
# rejection list; it is never an approved template.
_SVF_REJECTED_PLACEHOLDER_HASHES = frozenset({
    "a1b2c3d4e5f60718293a4b5c6d7e8f90a1b2c3d4e5f60718293a4b5c6d7e8f90",
    "00" * 32,
})


class SVFKeyError(ValueError):
    """Key-file validation failure. The node exits 1 on this error."""


def _svf_key_file_path(config=None):
    """Config key svf.key_file, or None when unset/empty."""
    cfg = config if isinstance(config, dict) else globals().get("CONFIG") or {}
    svf_cfg = cfg.get("svf") or {}
    if not isinstance(svf_cfg, dict):
        return None
    _kf = svf_cfg.get("key_file")
    if isinstance(_kf, str) and _kf.strip():
        return _kf.strip()
    return None


def _svf_load_key_file(key_file, config=None):
    """Load and validate the SVF committee key file (R3).

    Returns the parsed key dict and sets the module globals
    SVF_GROUP_PUBLIC_KEY, SVF_APPROVED_TEMPLATES, SVF_KEY_IS_TEST,
    SVF_KEY_CHAIN_ID, SVF_KEY_FILE and (test only) SVF_KEY_DKG.
    Raises SVFKeyError on any failure; the caller exits 1 and the
    message names the file. Never logs test_seed (R5).
    """
    global SVF_GROUP_PUBLIC_KEY, SVF_APPROVED_TEMPLATES, SVF_KEY_IS_TEST
    global SVF_KEY_CHAIN_ID, SVF_KEY_FILE, SVF_KEY_DKG
    if not key_file or not isinstance(key_file, str):
        raise SVFKeyError("svf.key_file is not set: no SVF key file configured")
    _path = str(key_file)
    try:
        _st = os.stat(_path)
    except FileNotFoundError:
        raise SVFKeyError(f"SVF key file not found: {_path}")
    except OSError as _e:
        raise SVFKeyError(f"SVF key file unreadable: {_path}: {_e}")
    if sys.platform != "win32":
        if int(_st.st_mode) & 0o044:
            raise SVFKeyError(
                f"SVF key file permissions are too open (group/other read): {_path}: "
                "chmod 0600 the key file")
    else:
        if int(_st.st_mode) & 0o044:
            logger.warning(f"[SVF] key file {_path} is group/other readable (Windows: WARNING only)")
    try:
        with open(_path, "r", encoding="utf-8") as _f:
            _raw = json.load(_f)
    except FileNotFoundError:
        raise SVFKeyError(f"SVF key file not found: {_path}")
    except (OSError, ValueError) as _e:
        raise SVFKeyError(f"SVF key file unreadable or invalid JSON: {_path}: {_e}")
    if not isinstance(_raw, dict):
        raise SVFKeyError(f"SVF key file must be a JSON object: {_path}")
    _chain_id = _raw.get("chain_id")
    if isinstance(_chain_id, bool) or not isinstance(_chain_id, int):
        raise SVFKeyError(f"SVF key file chain_id must be an integer: {_path}")
    if int(_chain_id) != int(CHAIN_ID):
        raise SVFKeyError(
            f"SVF key file chain_id {_chain_id} does not equal running chain id {int(CHAIN_ID)}: {_path}")
    _test = _raw.get("test")
    if not isinstance(_test, bool):
        raise SVFKeyError(f"SVF key file test must be a boolean: {_path}")
    if _test:
        if int(_chain_id) != 6621:
            raise SVFKeyError(f"SVF test key file chain_id must be 6621 (testnet): {_path}")
    else:
        if int(_chain_id) == 6621:
            raise SVFKeyError(f"SVF real key file chain_id must not be 6621 (testnet): {_path}")
        if "test_seed" in _raw:
            raise SVFKeyError(f"SVF real key file must not contain test_seed: {_path}")
        _cer = _raw.get("ceremony_record")
        if not isinstance(_cer, str) or not _cer.strip():
            raise SVFKeyError(f"SVF real key file ceremony_record must be non-empty: {_path}")
    _gpk_hex = _raw.get("group_public_key")
    if not isinstance(_gpk_hex, str):
        raise SVFKeyError(f"SVF key file group_public_key must be a hex string: {_path}")
    try:
        _gpk = bytes.fromhex(_gpk_hex.strip())
    except ValueError:
        raise SVFKeyError(f"SVF key file group_public_key is not valid hex: {_path}")
    if len(_gpk) != 96:
        raise SVFKeyError(f"SVF key file group_public_key must be 96 bytes: {_path}")
    try:
        _g1_from_bytes(_gpk)
    except Exception as _e:
        raise SVFKeyError(f"SVF key file group_public_key is not a valid G1 subgroup point: {_path}: {_e}")
    _templates = _raw.get("template_hashes")
    if not isinstance(_templates, list):
        raise SVFKeyError(f"SVF key file template_hashes must be a list: {_path}")
    _approved = {}
    _seen_hashes = set()
    for _t in _templates:
        if not isinstance(_t, dict):
            raise SVFKeyError(f"SVF key file template entry must be an object: {_path}")
        _name = _t.get("name")
        _sha = _t.get("sha256")
        _audit = _t.get("audit_ref")
        if not isinstance(_name, str) or not _name.strip():
            raise SVFKeyError(f"SVF key file template name must be a non-empty string: {_path}")
        if not isinstance(_sha, str):
            raise SVFKeyError(f"SVF key file template sha256 must be a hex string: {_path}")
        _sha_norm = _sha.strip().lower()
        if len(_sha_norm) != 64:
            raise SVFKeyError(f"SVF key file template sha256 must be 32 bytes (64 hex chars): {_path}")
        try:
            bytes.fromhex(_sha_norm)
        except ValueError:
            raise SVFKeyError(f"SVF key file template sha256 is not valid hex: {_path}")
        if not isinstance(_audit, str):
            raise SVFKeyError(f"SVF key file template audit_ref must be a string: {_path}")
        if _sha_norm in _SVF_REJECTED_PLACEHOLDER_HASHES:
            raise SVFKeyError(f"SVF key file template hash is a base placeholder value: {_path}")
        if _sha_norm in _seen_hashes:
            raise SVFKeyError(f"SVF key file template hashes must be unique: {_path}")
        if _name in _approved:
            raise SVFKeyError(f"SVF key file template names must be unique: {_path}")
        _seen_hashes.add(_sha_norm)
        _approved[_name] = _sha_norm
    _dkg = None
    if _test:
        _seed_hex = _raw.get("test_seed")
        if not isinstance(_seed_hex, str):
            raise SVFKeyError(f"SVF test key file test_seed must be present: {_path}")
        _seed_norm = _seed_hex.strip().lower()
        if len(_seed_norm) != 64:
            raise SVFKeyError(f"SVF test key file test_seed must be 64 hex chars: {_path}")
        try:
            _seed = bytes.fromhex(_seed_norm)
        except ValueError:
            raise SVFKeyError(f"SVF test key file test_seed is not valid hex: {_path}")
        _dkg = _svf_committee_dkg(_seed)
        if _dkg.get("group_public_key") != _gpk.hex():
            raise SVFKeyError(
                f"SVF test key file group_public_key does not match the key derived from test_seed: {_path}")
    SVF_GROUP_PUBLIC_KEY = _gpk
    SVF_APPROVED_TEMPLATES = dict(_approved)
    SVF_KEY_IS_TEST = bool(_test)
    SVF_KEY_CHAIN_ID = int(_chain_id)
    SVF_KEY_FILE = _path
    SVF_KEY_DKG = _dkg
    logger.info(f"[SVF] key file {_path}: chain_id={int(_chain_id)} test={bool(_test)} "
                f"group_public_key={_gpk.hex()}")
    for _name, _sha in sorted(_approved.items()):
        logger.info(f"[SVF] template {_name} sha256={_sha}")
    return {
        "chain_id": int(_chain_id), "test": bool(_test),
        "group_public_key": _gpk.hex(), "template_hashes": dict(_approved),
        "key_file": _path, "dkg": _dkg,
    }


def _svf_ensure_key_loaded(config=None):
    """Load the SVF key file once; exit 1 (naming the file) on failure.

    Safe to call from main() and from MicroCoreNode.start(). Importing
    this module does not load the key file.
    """
    global SVF_KEY_FILE
    if SVF_GROUP_PUBLIC_KEY is not None and SVF_KEY_FILE is not None:
        return {"chain_id": SVF_KEY_CHAIN_ID, "test": SVF_KEY_IS_TEST,
                "group_public_key": SVF_GROUP_PUBLIC_KEY.hex(),
                "template_hashes": dict(SVF_APPROVED_TEMPLATES),
                "key_file": SVF_KEY_FILE, "dkg": SVF_KEY_DKG}
    _kf = _svf_key_file_path(config)
    if _kf is None:
        # A key file this node generated itself on an earlier genesis
        # creation lives next to the genesis file: load it so the producer
        # keeps its signing key across restarts. Followers have no such
        # file and fall through to E4 unchanged.
        _default_kf = _svf_default_key_path()
        if os.path.isfile(_default_kf):
            try:
                return _svf_load_key_file(_default_kf, config=config)
            except SVFKeyError as _e:
                logger.error(f"[SVF] {_e}; refusing to start")
                sys.exit(1)
        # E4: no key file configured — do NOT exit. The node waits; SVF
        # public parameters are loaded from the genesis it receives over P2P
        # (or from its local genesis file) instead.
        logger.info("[SVF] svf.key_file is not set in config; waiting for SVF parameters from genesis (no key file configured)")
        return None
    try:
        return _svf_load_key_file(_kf, config=config)
    except SVFKeyError as _e:
        logger.error(f"[SVF] {_e}; refusing to start")
        sys.exit(1)


def _svf_public_for_genesis() -> dict:
    """Return the normalised svf_public dict for a new genesis body, from the
    producer's loaded SVF parameters (SVF_GROUP_PUBLIC_KEY,
    SVF_APPROVED_TEMPLATES, SVF_KEY_CHAIN_ID). Raises SVFKeyError naming the
    key file when no SVF parameters are loaded; the caller refuses to create
    a genesis and exits 1.
    """
    if SVF_GROUP_PUBLIC_KEY is None or SVF_KEY_CHAIN_ID is None:
        _kf = _svf_key_file_path()
        if _kf:
            raise SVFKeyError(f"SVF parameters not loaded from key file: {_kf}")
        raise SVFKeyError("SVF parameters not loaded: svf.key_file is not set in config; no SVF key file configured")
    return {
        "chain_id": int(SVF_KEY_CHAIN_ID),
        "group_public_key": SVF_GROUP_PUBLIC_KEY.hex(),
        "template_hashes": {k: v for k, v in sorted(SVF_APPROVED_TEMPLATES.items())},
    }


def _svf_default_key_path():
    """Default location for a node-generated testnet key file: next to the
    genesis file (GENESIS_FILE global, default 'genesis.json' in the cwd).
    The key file lives beside the genesis the node created, so the producer
    reloads its own signing key on restart."""
    _gf = globals().get("GENESIS_FILE") or "genesis.json"
    _d = os.path.dirname(os.path.abspath(str(_gf)))
    return os.path.join(_d, "svf_test_key.json")


def _svf_auto_generate_test_key():
    """Generate a fresh TESTNET SVF committee key, save it as the node's key
    file, and load it. Used only when creating a new genesis with no key
    file configured and the chain is the testnet (6621). The user is never
    asked to input a key, not even at genesis creation. The generated key
    is a test key (test_seed present, chain 6621) and can never be used for
    mainnet: the loader refuses a test key on any chain but 6621. Only
    public values are logged, never the seed."""
    _seed = os.urandom(32)
    _dkg = _svf_committee_dkg(_seed)
    _key = {
        "chain_id": 6621,
        "test": True,
        "group_public_key": _dkg["group_public_key"],
        "template_hashes": [dict(_t) for _t in _SVF_TESTNET_TEMPLATE_HASHES],
        "ceremony_record": "auto-generated testnet key (node-generated on genesis creation)",
        "test_seed": _seed.hex(),
    }
    _path = _svf_default_key_path()
    _fd = os.open(_path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    try:
        os.write(_fd, (json.dumps(_key, indent=2) + "\n").encode("utf-8"))
    finally:
        os.close(_fd)
    try:
        os.chmod(_path, 0o600)
    except OSError:
        pass
    _svf_load_key_file(_path)
    logger.info("[SVF] auto-generated testnet key file %s (chain 6621, group key %s...)", _path, _dkg["group_public_key"][:16])
    return _svf_public_for_genesis()


def _svf_load_from_genesis(svf_public):
    """Load SVF public parameters from a genesis body's svf_public field.

    Sets SVF_GROUP_PUBLIC_KEY, SVF_APPROVED_TEMPLATES, SVF_KEY_CHAIN_ID and
    SVF_KEY_IS_TEST. No-op when SVF parameters are already loaded (e.g. from
    a key file — E6, the key-file path wins) or when svf_public is absent.
    Uses the same subgroup check the key-file loader uses (_g1_from_bytes).
    Raises SVFKeyError naming the field on a malformed group key; the caller
    exits 1. Only public values are logged, never any seed or share.
    """
    global SVF_GROUP_PUBLIC_KEY, SVF_APPROVED_TEMPLATES, SVF_KEY_IS_TEST, SVF_KEY_CHAIN_ID
    if SVF_GROUP_PUBLIC_KEY is not None:
        return None
    if not svf_public:
        return None
    try:
        _norm = _normalize_svf_public(svf_public)
    except ValueError as _e:
        raise SVFKeyError(f"genesis svf_public is malformed: {_e}")
    if int(_norm["chain_id"]) != int(CHAIN_ID):
        raise SVFKeyError(
            f"genesis svf_public chain_id {_norm['chain_id']} does not equal running chain id {int(CHAIN_ID)}")
    try:
        _gpk = bytes.fromhex(_norm["group_public_key"])
    except ValueError:
        raise SVFKeyError("genesis svf_public group_public_key is not valid hex")
    if len(_gpk) != 96:
        raise SVFKeyError("genesis svf_public group_public_key must be 96 bytes")
    try:
        _g1_from_bytes(_gpk)
    except Exception as _e:
        raise SVFKeyError(f"genesis svf_public group_public_key is not a valid G1 subgroup point: {_e}")
    SVF_GROUP_PUBLIC_KEY = _gpk
    SVF_APPROVED_TEMPLATES = dict(_norm["template_hashes"])
    SVF_KEY_CHAIN_ID = int(_norm["chain_id"])
    SVF_KEY_IS_TEST = bool(int(_norm["chain_id"]) == 6621)
    logger.info(f"[SVF] loaded public parameters from genesis: chain_id={SVF_KEY_CHAIN_ID} test={SVF_KEY_IS_TEST} "
                f"group_public_key={_gpk.hex()}")
    for _name, _sha in sorted(SVF_APPROVED_TEMPLATES.items()):
        logger.info(f"[SVF] template {_name} sha256={_sha}")
    return {
        "chain_id": SVF_KEY_CHAIN_ID, "test": SVF_KEY_IS_TEST,
        "group_public_key": _gpk.hex(), "template_hashes": dict(SVF_APPROVED_TEMPLATES),
    }
BLS_SIG_DST = b"BLS_SIG_BLS12381G2_XMD:SHA-256_SSWU_RO_NUL_"



def _g1_to_bytes(point) -> bytes:
    """Serialize a G1 point (affine) as 96 bytes: x(48) + y(48), big-endian."""
    x, y, z = point
    if z != 1:
        point = normalize(point)
        x, y = point[0], point[1]
    x_val = int(x) if hasattr(x, '__int__') else int(x.coeffs[0])
    y_val = int(y) if hasattr(y, '__int__') else int(y.coeffs[0])
    return x_val.to_bytes(48, 'big') + y_val.to_bytes(48, 'big')


def _svf_in_prime_subgroup(point) -> bool:
    """Prime-order subgroup check using py_ecc's own multiply/is_inf."""
    try:
        return bool(is_inf(_bls_multiply(point, _BLS_CURVE_ORDER)))
    except Exception:
        return False


def _g1_from_bytes(data: bytes):
    """Deserialize a G1 point from 96 bytes: x(48) + y(48), big-endian.
    Rejects non-canonical encodings (coordinate >= field modulus),
    points not on the curve, and points outside the prime-order
    subgroup, using py_ecc's own checks."""
    if not isinstance(data, (bytes, bytearray)) or len(data) != 96:
        raise ValueError("G1 point must be exactly 96 bytes")
    x = int.from_bytes(data[0:48], 'big')
    y = int.from_bytes(data[48:96], 'big')
    if x >= _BLS_FIELD_MODULUS or y >= _BLS_FIELD_MODULUS:
        raise ValueError("G1 coordinate out of field range")
    pt = (FQ(x), FQ(y), FQ(1))
    if not is_on_curve(pt, b):
        raise ValueError("G1 point not on curve")
    if not _svf_in_prime_subgroup(pt):
        raise ValueError("G1 point not in prime-order subgroup")
    return pt


def _g2_to_bytes(point) -> bytes:
    """Serialize a G2 point (affine) as 192 bytes: x(96) + y(96), big-endian."""
    x, y, z = point
    z_is_one = False
    if hasattr(z, 'coeffs'):
        z_is_one = (z.coeffs[0] == 1 and z.coeffs[1] == 0)
    elif z == (1, 0) or z == 1:
        z_is_one = True
    if not z_is_one:
        point = normalize(point)
        x, y = point[0], point[1]
    x0 = int(x.coeffs[0]) if hasattr(x, 'coeffs') else int(x[0])
    x1 = int(x.coeffs[1]) if hasattr(x, 'coeffs') else int(x[1])
    y0 = int(y.coeffs[0]) if hasattr(y, 'coeffs') else int(y[0])
    y1 = int(y.coeffs[1]) if hasattr(y, 'coeffs') else int(y[1])
    x_bytes = x0.to_bytes(48, 'big') + x1.to_bytes(48, 'big')
    y_bytes = y0.to_bytes(48, 'big') + y1.to_bytes(48, 'big')
    return x_bytes + y_bytes


def _g2_from_bytes(data: bytes):
    """Deserialize a G2 point from 192 bytes: x(96) + y(96), big-endian.
    Rejects non-canonical encodings (coordinate >= field modulus),
    points not on the curve, and points outside the prime-order
    subgroup, using py_ecc's own checks."""
    if not isinstance(data, (bytes, bytearray)) or len(data) != 192:
        raise ValueError("G2 point must be exactly 192 bytes")
    x0 = int.from_bytes(data[0:48], 'big')
    x1 = int.from_bytes(data[48:96], 'big')
    y0 = int.from_bytes(data[96:144], 'big')
    y1 = int.from_bytes(data[144:192], 'big')
    if (x0 >= _BLS_FIELD_MODULUS or x1 >= _BLS_FIELD_MODULUS
            or y0 >= _BLS_FIELD_MODULUS or y1 >= _BLS_FIELD_MODULUS):
        raise ValueError("G2 coordinate out of field range")
    pt = (FQ2([x0, x1]), FQ2([y0, y1]), FQ2([1, 0]))
    if not is_on_curve(pt, b2):
        raise ValueError("G2 point not on curve")
    if not _svf_in_prime_subgroup(pt):
        raise ValueError("G2 point not in prime-order subgroup")
    return pt



def _svf_bls_keygen(seed: bytes) -> tuple:
    """Generate a BLS12-381 key pair. Returns (private_key_int, public_key_bytes)."""
    sk_int = int.from_bytes(seed, 'big') % _BLS_CURVE_ORDER
    if sk_int == 0:
        sk_int = 1
    pk = _bls_multiply(G1, sk_int)
    return sk_int, _g1_to_bytes(pk)


def _svf_bls_sk_to_pk(sk_int: int) -> bytes:
    """Convert private key int to public key bytes."""
    pk = _bls_multiply(G1, sk_int % _BLS_CURVE_ORDER)
    return _g1_to_bytes(pk)


def _svf_bls_sign(sk_int: int, message: bytes) -> bytes:
    """Sign message with BLS private key. Returns 192-byte signature (uncompressed G2)."""
    h_msg = hash_to_G2(message, BLS_SIG_DST, sha256)
    sig = _bls_multiply(h_msg, sk_int % _BLS_CURVE_ORDER)
    return _g2_to_bytes(sig)


def _svf_bls_verify(pk_bytes: bytes, message: bytes, sig_bytes: bytes) -> bool:
    """Verify BLS signature. Returns True if valid."""
    try:
        pk = _g1_from_bytes(pk_bytes)
        sig = _g2_from_bytes(sig_bytes)
        h_msg = hash_to_G2(message, BLS_SIG_DST, sha256)
        left = final_exponentiate(pairing(h_msg, pk))
        right = final_exponentiate(pairing(sig, G1))
        return left == right
    except Exception:
        return False


# ─── Shamir secret sharing ──────────────────────────────────────────────

def _svf_shamir_share(sk_int: int, n: int, t: int) -> list:
    """Split private key into n shares with threshold t using Shamir secret sharing.
    
    Returns list of (share_index, share_value) tuples, index starting at 1.
    """
    import secrets as _secrets
    coeffs = [sk_int % _BLS_CURVE_ORDER]
    for _ in range(1, t):
        coeffs.append(_secrets.randbelow(_BLS_CURVE_ORDER))

    def _eval_poly(x, coeffs):
        result = 0
        for c in reversed(coeffs):
            result = (result * x + c) % _BLS_CURVE_ORDER
        return result

    shares = []
    for i in range(1, n + 1):
        shares.append((i, _eval_poly(i, coeffs)))
    return shares


def _svf_shamir_reconstruct(shares: list, p: int = _BLS_CURVE_ORDER) -> int:
    """Reconstruct secret from shares using Lagrange interpolation at x=0."""
    x_vals = [s[0] for s in shares]
    y_vals = [s[1] for s in shares]
    k = len(shares)
    result = 0
    for i in range(k):
        xi, yi = x_vals[i], y_vals[i]
        li = 1
        for j in range(k):
            if i != j:
                xj = x_vals[j]
                li = (li * (0 - xj) * pow(xi - xj, -1, p)) % p
        result = (result + yi * li) % p
    return result



def _svf_committee_dkg(seed: bytes, n: int = SVF_COMMITTEE_N,
                       t: int = SVF_COMMITTEE_THRESHOLD) -> dict:
    """Distributed Key Generation simulation (TEST ONLY).
    
    Generates a master BLS key and splits it into n shares with threshold t.
    Returns committee config with member public keys and shares.
    
    WARNING: This is a test-only simulation. In production, DKG must be a
    genuine multi-party protocol where each committee member independently
    contributes to key generation and no single party learns the master
    secret. The master secret key is intentionally NOT returned here.
    The group public key is derived as sk * G1 from the master secret for
    test verification purposes only.
    
    Production deployment requires:
    - Independent committee members each generating their own key shares
    - A DKG protocol (e.g., Gennaro et al. or Kate et al.) where members
      exchange commitments and verify each other's contributions
    - The group public key computed as sum of individual public contributions
    - No single party ever knowing the full master secret
    """
    sk_int, pk_bytes = _svf_bls_keygen(seed)
    shares = _svf_shamir_share(sk_int, n, t)
    member_shares = {}
    member_pubkeys = []
    for i, share_val in shares:
        member_shares[i] = share_val
        member_pubkeys.append(_svf_bls_sk_to_pk(share_val))

    return {
        "committee_epoch": SVF_COMMITTEE_EPOCH,
        "group_public_key": pk_bytes.hex(),
        "threshold": t,
        "member_count": n,
        "member_pubkeys": [pk.hex() for pk in member_pubkeys],
        "member_shares": {str(i): v for i, v in shares},
    }


def _svf_committee_partial_sign(share_sk_int: int, message: bytes) -> bytes:
    """Generate a partial BLS signature from a key share."""
    return _svf_bls_sign(share_sk_int, message)


def _svf_committee_verify_partial(share_pk_bytes: bytes, message: bytes,
                                   partial_sig_bytes: bytes) -> bool:
    """Verify a partial signature against a member's public key share."""
    return _svf_bls_verify(share_pk_bytes, message, partial_sig_bytes)


def _svf_committee_combine_partials(partial_sigs: list, shares: list,
                                     message: bytes, p: int = _BLS_CURVE_ORDER) -> bytes:
    """Combine threshold partial signatures into a full BLS signature.
    
    Uses Lagrange interpolation on G2 elements:
      combined_sig = sum(L_i(0) * partial_sig_i)
    
    Each partial signature is a G2 element. We scale each by its Lagrange
    coefficient using G2 scalar multiplication and add them in G2.
    The master secret key is never reconstructed.
    """
    if not partial_sigs or not shares or len(partial_sigs) != len(shares):
        raise SVFReject("partial signatures and shares must be non-empty and equal length")
    x_vals = [s[0] for s in shares]
    k = len(shares)
    lagrange_coeffs = []
    for i in range(k):
        xi = x_vals[i]
        li = 1
        for j in range(k):
            if i != j:
                xj = x_vals[j]
                li = (li * (0 - xj) * pow(xi - xj, -1, p)) % p
        lagrange_coeffs.append(li % p)

    combined = None
    for li, sig_bytes in zip(lagrange_coeffs, partial_sigs):
        sig = _g2_from_bytes(sig_bytes)
        scaled = _bls_multiply(sig, int(li))
        if combined is None:
            combined = scaled
        else:
            combined = _bls_add(combined, scaled)

    if combined is None:
        raise SVFReject("no partial signatures to combine")

    return _g2_to_bytes(combined)


def _svf_committee_generate_certificate(dkg_config: dict, evidence_root: bytes,
                                         chain_id: int, committee_epoch: int,
                                         evidence_epoch: int,
                                         window_start: int, window_end: int,
                                         anchor_hash: str) -> dict:
    """Generate a threshold-BLS epoch beacon certificate.
    
    Committee members produce partial signatures over the canonical beacon
    message; t-of-n partials are combined into the final threshold signature.
    """
    import hashlib as _hashlib
    import struct as _struct

    msg = b"MCX-SVF-EPOCH-BEACON-V1"
    msg += _struct.pack(">H", 1)
    msg += _struct.pack(">Q", chain_id)
    msg += _struct.pack(">Q", committee_epoch)
    msg += _struct.pack(">Q", evidence_epoch)
    msg += _struct.pack(">Q", window_start)
    msg += _struct.pack(">Q", window_end)
    msg += bytes.fromhex(anchor_hash)
    msg += evidence_root
    # NOTE (Run11 cert fix 1): PRUNE_BLOCKS is deliberately NOT part of
    # the signed message. It is a local node config value; including it
    # made a certificate signed by a prune-100 node unverifiable on a
    # prune-200 node. The canonical message is the same on every node.

    t = dkg_config["threshold"]
    n = dkg_config["member_count"]

    partials = []
    member_ids = sorted(int(k) for k in dkg_config["member_shares"].keys())
    for mid in member_ids[:t]:
        share_sk = dkg_config["member_shares"][str(mid)]
        partial_sig = _svf_committee_partial_sign(share_sk, msg)
        partials.append((mid, partial_sig))

    member_pubkeys = dkg_config["member_pubkeys"]
    share_pks = []
    for mid in member_ids[:t]:
        _pk = member_pubkeys[mid - 1]
        share_pks.append(bytes.fromhex(_pk) if isinstance(_pk, str) else _pk)

    for (mid, psig), spk in zip(partials, share_pks):
        if not _svf_committee_verify_partial(spk, msg, psig):
            raise SVFReject(f"Partial signature verification failed for member {mid}")

    selected_shares = [(mid, dkg_config["member_shares"][str(mid)]) for mid in member_ids[:t]]
    partial_sig_bytes = [psig for _, psig in partials]
    threshold_sig = _svf_committee_combine_partials(
        partial_sig_bytes, selected_shares, msg)

    group_pk = bytes.fromhex(dkg_config["group_public_key"])
    if not _svf_bls_verify(group_pk, msg, threshold_sig):
        raise SVFReject("Combined threshold signature verification failed")

    beacon_output = _hashlib.sha256(
        b"MCX-SVF-BEACON-OUTPUT-V1" + b"\x00" + threshold_sig
    ).digest()

    return {
        "protocol_version": 1,
        "chain_id": chain_id,
        "committee_epoch": committee_epoch,
        "evidence_epoch": evidence_epoch,
        "window_start_height": window_start,
        "window_end_height": window_end,
        "anchor_block_hash": anchor_hash,
        "evidence_root": evidence_root.hex() if isinstance(evidence_root, bytes) else evidence_root,
        "group_public_key_id": dkg_config["group_public_key"],
        "group_pubkey": dkg_config["group_public_key"],
        "threshold_signature": threshold_sig.hex(),
        "beacon_output": beacon_output.hex(),
        "canonical_message": msg.hex(),
    }
_SVF_PROFILE_REGISTRY: dict = {}

_SVF_EVIDENCE_STORE: dict = {}

_SVF_EPOCH_ROOTS: dict = {}

_SVF_CERTIFICATE_STORE: dict = {}


def svf_profile_hash(chain_id: int, token_address: str, profile_bytes: bytes) -> bytes:
    """Canonical profile hash: SHA256(domain || chain_id || token_address || profile_bytes)."""
    _tok = str(token_address).lower() if isinstance(token_address, str) else ""
    if _tok and not _tok.startswith("0x"):
        _tok = "0x" + _tok
    if not _valid_wallet(_tok):
        raise SVFReject("invalid token address for profile hash")
    if not isinstance(profile_bytes, (bytes, bytearray)) or len(profile_bytes) != SVF_PROFILE_SIZE:
        raise SVFReject("profile_bytes must be exactly 42 bytes")
    h = hashlib.sha256()
    h.update(SVF_PROFILE_DOMAIN)
    h.update(struct.pack(">Q", int(chain_id)))
    tok = _tok.lower()
    if tok.startswith("0x"):
        tok = tok[2:]
    h.update(bytes.fromhex(tok))
    h.update(bytes(profile_bytes))
    return h.digest()


def svf_parse_profile(raw: bytes) -> dict:
    """Parse canonical 42-byte profile encoding into a dict."""
    if not isinstance(raw, (bytes, bytearray)) or len(raw) != SVF_PROFILE_SIZE:
        raise SVFReject("profile must be exactly 42 bytes")
    if raw[:4] != SVF_PROFILE_MAGIC:
        raise SVFReject("invalid profile magic")
    schema_version = struct.unpack(">H", raw[4:6])[0]
    if schema_version != SVF_PROFILE_SCHEMA_VERSION:
        raise SVFReject(f"unsupported profile schema version: {schema_version}")
    family_id = raw[6]
    if family_id != SVF_PROFILE_FAMILY_ID:
        raise SVFReject(f"unsupported profile family: {family_id}")
    sample_blocks = raw[7]
    min_distinct_winners = raw[8]
    min_growth_blocks = raw[9]
    min_total_attestation_weight = int.from_bytes(raw[10:42], "big")
    
    if not (1 <= sample_blocks <= SVF_EPOCH_BLOCKS):
        raise SVFReject(f"sample_blocks out of range [1, {SVF_EPOCH_BLOCKS}]: {sample_blocks}")
    if not (1 <= min_distinct_winners <= sample_blocks):
        raise SVFReject(f"min_distinct_winners out of range [1, {sample_blocks}]: {min_distinct_winners}")
    if not (0 <= min_growth_blocks <= sample_blocks):
        raise SVFReject(f"min_growth_blocks out of range [0, {sample_blocks}]: {min_growth_blocks}")
    if min_total_attestation_weight <= 0:
        raise SVFReject("min_total_attestation_weight must be positive")
    
    return {
        "schema_version": schema_version,
        "family_id": family_id,
        "sample_blocks": sample_blocks,
        "min_distinct_winners": min_distinct_winners,
        "min_growth_blocks": min_growth_blocks,
        "min_total_attestation_weight": min_total_attestation_weight,
    }


def svf_profile_bytes(profile: dict) -> bytes:
    """Encode profile dict to canonical 42-byte binary."""
    if profile["schema_version"] != SVF_PROFILE_SCHEMA_VERSION:
        raise SVFReject(f"unsupported schema version: {profile['schema_version']}")
    if profile["family_id"] != SVF_PROFILE_FAMILY_ID:
        raise SVFReject(f"unsupported family id: {profile['family_id']}")
    sb = bytearray()
    sb += SVF_PROFILE_MAGIC
    sb += struct.pack(">H", profile["schema_version"])
    sb += bytes([profile["family_id"]])
    sb += bytes([profile["sample_blocks"]])
    sb += bytes([profile["min_distinct_winners"]])
    sb += bytes([profile["min_growth_blocks"]])
    sb += profile["min_total_attestation_weight"].to_bytes(32, "big")
    return bytes(sb)


class SVFBlockEvidence:
    """Consensus-critical per-block evidence summary."""

    def __init__(self, block_id: int, block_hash: str, winner_pubkey: str,
                 attested_size: int, attestation_weight: int, growth_present: bool,
                 record_hash: bytes):
        self.block_id = block_id
        self.block_hash = block_hash
        self.winner_pubkey = winner_pubkey.lower()
        self.attested_size = attested_size
        self.attestation_weight = attestation_weight
        self.growth_present = growth_present
        self.record_hash = record_hash if isinstance(record_hash, bytes) else bytes.fromhex(record_hash)


def compute_block_evidence(block: dict, block_id: int) -> SVFBlockEvidence:
    """Extract consensus-critical evidence from a sealed block.

    Reads maze_attestation and maze_updates from the block's top-level fields
    (exactly as verify_block_proof validates them). Returns an SVFBlockEvidence
    or raises SVFReject if the block lacks valid proof data.
    """
    att = block.get("maze_attestation")
    if not isinstance(att, dict):
        raise SVFReject("block has no maze_attestation")
    attested_size = int(att.get("size", 0))
    if attested_size <= 0:
        raise SVFReject("attestation size must be positive")

    maze_updates = block.get("maze_updates", [])
    if not isinstance(maze_updates, list):
        raise SVFReject("block maze_updates is not a list")

    att_pub = str(att.get("pubkey", "") or "")
    if not att_pub:
        raise SVFReject("maze_attestation has no pubkey")
    winner_pubkey = att_pub.lower()

    winner = block.get("winner") or att_pub
    growth_present = False
    for upd in maze_updates:
        if not isinstance(upd, dict):
            continue
        _um = str(upd.get("maze_id") or upd.get("miner_id") or "")
        if _um != str(winner):
            continue
        _type = str(upd.get("type", "") or "")
        if _type in ("goal_catch", "growth", "maze_update") and upd.get("caught_at_nonce") is not None:
            growth_present = True
            break
        if upd.get("new_size") is not None and upd.get("caught_at_nonce") is not None:
            growth_present = True
            break

    att_weight = _maze_att_weight(attested_size)

    block_hash = block.get("hash")
    if not block_hash:
        raise SVFReject("block has no hash")
    block_hash_bytes = bytes.fromhex(block_hash) if isinstance(block_hash, str) else bytes(block_hash)
    winner_pubkey_bytes = bytes.fromhex(winner_pubkey.removeprefix("0x")) if winner_pubkey.startswith("0x") else bytes.fromhex(winner_pubkey)

    h = hashlib.sha256()
    h.update(SVF_EVIDENCE_DOMAIN)
    h.update(struct.pack(">Q", int(block_id)))
    h.update(block_hash_bytes)
    h.update(winner_pubkey_bytes)
    h.update(struct.pack(">Q", attested_size))
    h.update(struct.pack(">Q", att_weight))
    h.update(b"\x01" if growth_present else b"\x00")
    record_hash = h.digest()

    return SVFBlockEvidence(
        block_id=block_id,
        block_hash=block_hash,
        winner_pubkey=winner_pubkey,
        attested_size=attested_size,
        attestation_weight=att_weight,
        growth_present=growth_present,
        record_hash=record_hash,
    )


def compute_epoch_root(records: list) -> bytes:
    """Compute canonical Merkle root over exactly 100 sorted evidence records.

    Accepts either dicts (with "block_id"/"record_hash" keys) or
    SVFBlockEvidence objects (with .block_id/.record_hash attributes).
    """
    if len(records) != SVF_EPOCH_BLOCKS:
        raise SVFReject(f"epoch root requires exactly {SVF_EPOCH_BLOCKS} records, got {len(records)}")

    def _get(rec, key):
        if isinstance(rec, dict):
            return rec[key]
        return getattr(rec, key)

    sorted_recs = sorted(records, key=lambda r: _get(r, "block_id"))
    level = [hashlib.sha256(SVF_EVIDENCE_LEAF_DOMAIN + b"\x00" + _get(r, "record_hash")).digest() for r in sorted_recs]
    while len(level) > 1:
        nxt = []
        for i in range(0, len(level) - 1, 2):
            nxt.append(hashlib.sha256(SVF_EVIDENCE_NODE_DOMAIN + b"\x00" + level[i] + level[i + 1]).digest())
        if len(level) % 2 == 1:
            nxt.append(level[-1])
        level = nxt
    return level[0]


def _svf_epoch_root_if_complete(records, epoch_id):
    valid = [r for r in (records or []) if r is not None]
    if len(valid) != SVF_EPOCH_BLOCKS:
        return None
    def _bid(r):
        return r["block_id"] if isinstance(r, dict) else r.block_id
    srt = sorted(valid, key=_bid)
    if [int(_bid(r)) for r in srt] != list(range(epoch_id * SVF_EPOCH_BLOCKS,
                                          epoch_id * SVF_EPOCH_BLOCKS + SVF_EPOCH_BLOCKS)):
        return None
    return compute_epoch_root(srt)


def compute_epoch_challenge(beacon: bytes, chain_id: int, epoch_id: int,
                            token_address: str, profile_hash: bytes,
                            evidence_root: bytes) -> bytes:
    """Compute the profile-specific challenge seed for an epoch.

    challenge_seed = SHA256("MCX-SVF-CHALLENGE-SEED-V1" || 0x00 ||
        uint64_be(chain_id) || uint64_be(evidence_epoch) ||
        token_address_20 || profile_hash_32 || evidence_root_32 ||
        beacon_output_32)
    """
    if not isinstance(beacon, (bytes, bytearray)) or len(beacon) != 32:
        raise SVFReject("beacon must be 32 bytes")
    _svf_int("chain_id", chain_id, 0, 2 ** 63 - 1)
    _svf_int("evidence_epoch", epoch_id, 0, 2 ** 63 - 1)
    _tok = str(token_address).lower() if isinstance(token_address, str) else ""
    if _tok and not _tok.startswith("0x"):
        _tok = "0x" + _tok
    if not _valid_wallet(_tok):
        raise SVFReject("invalid token address for challenge")
    token_address = _tok
    if isinstance(profile_hash, (bytes, bytearray)):
        if len(profile_hash) != 32:
            raise SVFReject("profile_hash must be 32 bytes")
        profile_hash_hex = bytes(profile_hash).hex()
    elif isinstance(profile_hash, str):
        _svf_hex32("profile_hash", profile_hash)
        profile_hash_hex = profile_hash
    else:
        raise SVFReject("profile_hash must be 32 bytes or 64-char hex string")
    if isinstance(evidence_root, (bytes, bytearray)):
        if len(evidence_root) != 32:
            raise SVFReject("evidence_root must be 32 bytes")
        evidence_root_hex = bytes(evidence_root).hex()
    elif isinstance(evidence_root, str):
        _svf_hex32("evidence_root", evidence_root)
        evidence_root_hex = evidence_root
    else:
        raise SVFReject("evidence_root must be 32 bytes or 64-char hex string")

    h = hashlib.sha256()
    h.update(SVF_CHALLENGE_DOMAIN)
    h.update(b"\x00")
    h.update(struct.pack(">Q", chain_id))
    h.update(struct.pack(">Q", epoch_id))
    tok = token_address.lower().removeprefix("0x")
    h.update(bytes.fromhex(tok))
    h.update(bytes.fromhex(profile_hash_hex))
    h.update(bytes.fromhex(evidence_root_hex))
    h.update(bytes(beacon))
    return h.digest()


def fisher_yates_shuffle(challenge_seed: bytes, n: int) -> list:
    """Deterministic Fisher-Yates shuffle of indices 0..n-1 using challenge_seed.

    Uses HMAC-SHA256 with rejection sampling to avoid modulo bias.
    For each step i (from n-1 down to 1), j is drawn uniformly from [0, i].

    Returns a list of indices in shuffled order.
    """
    import hmac as _hmac
    if n <= 0:
        return []
    if n == 1:
        return [0]
    permutation = list(range(n))
    counter = 0
    for i in range(n - 1, 0, -1):
        n_step = i + 1
        limit = (2 ** 256 // n_step) * n_step
        while True:
            counter += 1
            msg = SVF_FY_DOMAIN + struct.pack(">I", counter)
            digest = _hmac.new(challenge_seed, msg, hashlib.sha256).digest()
            x = int.from_bytes(digest, "big")
            if x < limit:
                break
        j = x % n_step
        permutation[i], permutation[j] = permutation[j], permutation[i]
    return permutation


def _svf_rec_get(rec, key, default=None):
    if isinstance(rec, dict):
        return rec.get(key, default)
    return getattr(rec, key, default)


def evaluate_profile(profile: dict, evidence_records: list, block_id: int,
                     challenge_seed: bytes = None, epoch_root: bytes = None,
                     certificate: dict = None, chain_id: int = None,
                     token_address: str = None, profile_hash: bytes = None,
                     prune_blocks: int = 0) -> str:
    """Evaluate a profile against a validated evidence epoch.

    Returns "PASS", "FAIL", or "UNAVAILABLE".

    The evaluation:
      1. Confirms the exact 100-record epoch sequence.
      2. Confirms the canonical epoch root matches.
      3. Confirms evidence maturity (end_height + PRUNE_BLOCKS < block_id).
      4. Verifies the certificate/beacon is present and valid.
      5. Derives the profile-specific challenge seed.
      6. Selects the exact sample via HMAC-SHA256 Fisher-Yates.
      7. Evaluates thresholds on the selected records only.

    Missing/unavailable certificate or evidence -> UNAVAILABLE (not FAIL).
    Invalid certificate or corrupt root -> FAIL (invalid consensus data).
    """
    if not evidence_records:
        return "UNAVAILABLE"
    if any(r is None for r in evidence_records):
        return "UNAVAILABLE"

    sample_blocks = int(profile.get("sample_blocks", 0))
    if not (1 <= sample_blocks <= SVF_EPOCH_BLOCKS):
        return "UNAVAILABLE"

    if len(evidence_records) != SVF_EPOCH_BLOCKS:
        return "UNAVAILABLE"
    sorted_recs = sorted(evidence_records, key=lambda r: _svf_rec_get(r, "block_id", 0))
    expected_heights = []
    epoch_id = sorted_recs[0].get("block_id", 0) // SVF_EPOCH_BLOCKS
    for k in range(SVF_EPOCH_BLOCKS):
        expected_heights.append(epoch_id * SVF_EPOCH_BLOCKS + k)
    actual_heights = [int(_svf_rec_get(r, "block_id", -1)) for r in sorted_recs]
    if actual_heights != expected_heights:
        return "UNAVAILABLE"

    if epoch_root is not None:
        try:
            computed_root = compute_epoch_root(sorted_recs)
            if computed_root != (epoch_root if isinstance(epoch_root, bytes) else bytes.fromhex(epoch_root)):
                return "FAIL"
        except SVFReject:
            return "FAIL"

    end_height = epoch_id * SVF_EPOCH_BLOCKS + SVF_EPOCH_BLOCKS - 1
    if not (end_height + int(prune_blocks) < int(block_id)):
        return "UNAVAILABLE"

    if certificate is None:
        return "UNAVAILABLE"
    cert_sig = certificate.get("threshold_signature") or certificate.get("signature")
    if not cert_sig:
        return "UNAVAILABLE"
    try:
        sig_bytes = bytes.fromhex(cert_sig) if isinstance(cert_sig, str) else bytes(cert_sig)
    except (ValueError, TypeError):
        return "UNAVAILABLE"
    if len(sig_bytes) == 0:
        return "UNAVAILABLE"
    beacon_output = hashlib.sha256(
        b"MCX-SVF-BEACON-OUTPUT-V1" + b"\x00" + sig_bytes
    ).digest()

    if challenge_seed is None:
        if chain_id is None or token_address is None or profile_hash is None or epoch_root is None:
            return "UNAVAILABLE"
        try:
            challenge_seed = compute_epoch_challenge(
                beacon_output, int(chain_id), epoch_id,
                token_address, profile_hash, epoch_root)
        except SVFReject:
            return "UNAVAILABLE"

    permutation = fisher_yates_shuffle(challenge_seed, SVF_EPOCH_BLOCKS)
    selected_indices = sorted(permutation[:sample_blocks])

    sampled_weight = 0
    sampled_winners = set()
    sampled_growth = 0
    for idx in selected_indices:
        rec = sorted_recs[idx]
        sampled_weight += int(_svf_rec_get(rec, "attestation_weight", 0))
        sampled_winners.add(_svf_rec_get(rec, "winner_pubkey"))
        if _svf_rec_get(rec, "growth_present"):
            sampled_growth += 1

    min_weight = int(profile.get("min_total_attestation_weight", 0))
    min_distinct = int(profile.get("min_distinct_winners", 0))
    min_growth = int(profile.get("min_growth_blocks", 0))

    if (sampled_weight >= min_weight and
            len(sampled_winners) >= min_distinct and
            sampled_growth >= min_growth):
        return "PASS"
    return "FAIL"



def pubkey_to_address(pub_hex: str) -> str:
    pub_hex = pub_hex.removeprefix("0x")
    if pub_hex.startswith("04"):
        pub_bytes = bytes.fromhex(pub_hex)
        if len(pub_bytes) != 65 or pub_bytes[0] != 0x04:
            raise ValueError("Expected an uncompressed secp256k1 public key")
        return "0x" + eth_keccak(pub_bytes[1:])[-20:].hex()
    return pub_hex if pub_hex.startswith("0x") else "0x" + pub_hex

def checksum_address(addr: str) -> str:
    raw = addr.lower().removeprefix("0x")
    if len(raw) != 40 or not all(ch in "0123456789abcdef" for ch in raw):
        raise ValueError("Invalid address")
    digest = eth_keccak(raw.encode("ascii")).hex()
    return "0x" + "".join(
        ch.upper() if ch in "abcdef" and int(digest[i], 16) >= 8 else ch
        for i, ch in enumerate(raw)
    )

# CORS fix: node REST/RPC responses must never carry a wildcard origin
_LOCALHOST_ORIGIN_RE = re.compile(r"^https?://(localhost|127\.0\.0\.1|\[::1\])(:\d+)?$")

def _cors_origin_allowed(origin) -> bool:
    if not origin or not isinstance(origin, str):
        return False
    return bool(_LOCALHOST_ORIGIN_RE.match(origin))


def _validate_ws_bind(ws_bind_ip, ws_port, api_port):
    """ESP-WS-1: validate the miner-WebSocket listener before binding.
    Returns (bind_ip, ws_port, api_port) with ports as ints. Raises
    ValueError naming the bad value (fail clearly instead of an asyncio
    bind traceback). `0.0.0.0`/`::`/''/`all` = all interfaces (LAN miners);
    otherwise a valid IPv4/IPv6 literal is required (hostnames are NOT
    resolved here — put an IP literal or the wildcard in config)."""
    _bind = str(ws_bind_ip if ws_bind_ip not in (None, "") else "0.0.0.0")
    if _bind.lower() == "all":
        _bind = "0.0.0.0"
    if _bind not in ("0.0.0.0", "::"):
        try:
            ipaddress.ip_address(_bind)
        except ValueError:
            raise ValueError(
                f"node.ws_bind_ip must be 0.0.0.0, ::, or a valid IP literal, got {_bind!r}")
    for _name, _p in (("node.ws_port", ws_port), ("node.api_port", api_port)):
        if isinstance(_p, bool):
            raise ValueError(f"{_name} must be an integer port 1..65535, got {_p!r}")
        try:
            _pi = int(str(_p).strip()) if isinstance(_p, str) else int(_p)
        except (TypeError, ValueError):
            raise ValueError(f"{_name} must be an integer port 1..65535, got {_p!r}")
        if isinstance(_p, float) or not 1 <= _pi <= 65535:
            raise ValueError(f"{_name} must be an integer port 1..65535, got {_p!r}")
    return _bind, int(ws_port), int(api_port)


def _detect_lan_ip() -> str:
    """Best-effort LAN IPv4 for log lines (UDP connect trick; no traffic
    sent). Falls back to loopback. Pure best-effort; never raises."""
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        lan_ip = s.getsockname()[0]
        s.close()
        return lan_ip or "127.0.0.1"
    except Exception:
        return "127.0.0.1"


class _BadInt(ValueError):
    """Raised by _rint/_rfloat with the offending field name as arg."""


def _rint(data, key, default=0):
    """Strict int for REST fields (J6 audit): garbage yields _BadInt
    (callers answer 400) instead of an unhandled 500."""
    try:
        return int(data.get(key, default))
    except (TypeError, ValueError):
        raise _BadInt(key)


def _rfloat_opt(data, key):
    """Optional float field; None when absent, _BadInt on garbage."""
    if key not in data:
        return None
    try:
        return float(data.get(key))
    except (TypeError, ValueError):
        raise _BadInt(key)


def _ws_page_params(data):
    """Bounded pagination for WS list routes (J5a audit): limit coerced
    to int in [1,500] (default 10), offset clamped >= 0 (default 0).
    Unbounded/garbage values previously drove multi-MB dumps or DB errors."""
    try:
        _lim = int(data.get("limit", 10))
    except (TypeError, ValueError):
        _lim = 10
    try:
        _off = int(data.get("offset", 0))
    except (TypeError, ValueError):
        _off = 0
    return max(1, min(_lim, 500)), max(0, _off)


def _ws_health_handler(request):
    """ESP-WS-1: minimal transport diagnostic on the PUBLIC miner-WS app.
    Exact contract {"status": "ok", "service": "mcx-miner-ws"} — nothing
    else may ever appear here (no secrets, config, wallet, chain or peer
    data of any kind)."""
    from aiohttp import web
    return web.json_response({"status": "ok", "service": "mcx-miner-ws"})


def _ws_app_routes(app, websocket_handler):
    """Register the public miner-WS app routes in one place (keeps the
    route table reviewable and unit-testable without booting a node)."""
    app.router.add_get('/ws', websocket_handler)
    app.router.add_get('/healthz', _ws_health_handler)
    return app


# --- AUTO-SECRETS-1: node secret-file helpers -----------------------------
# Part 3: one helper defines where secret files live. Secrets are stored
# in the node's data directory, never in config.yaml (config.yaml keeps

_SECRETS_DIR_CACHE: Optional[str] = None
_RPC_TOKEN_FILE_CACHE: Optional[str] = None
_RPC_TOKEN_FILE_TRIED = False


def _wallet_file_path() -> str:
    """wallet.json: the encrypted wallet key, kept out of config.yaml."""
    return os.path.join(os.path.dirname(os.path.abspath(CONFIG_PATH)), 'wallet.json')


def _read_wallet_file() -> dict:
    try:
        with open(_wallet_file_path(), 'r') as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}


def _save_wallet_file(encrypted: str, address: str, pub: str) -> str:
    path = _wallet_file_path()
    data = json.dumps({'address': address, 'public_key': pub,
                       'private_key_encrypted': encrypted}, indent=2).encode('utf-8')
    _write_secret_file(path, data)
    return path


def _strip_wallet_from_config() -> None:
    if not os.path.exists(CONFIG_PATH):
        return
    with open(CONFIG_PATH, 'r') as f:
        d = yaml.safe_load(f) or {}
    d.pop('private_key_encrypted', None)
    d.pop('public_key', None)
    with open(CONFIG_PATH, 'w') as f:
        yaml.dump(d, f)


def _secrets_dir(config=None) -> str:
    """AUTO-SECRETS-1: the directory that holds the node's secret files
    (rpc_token; AUTO-WALLET-A (D3): there is no wallet-password file in
    this build).

    Chosen path: the directory containing the SQLite database file when
    the effective database.url is a sqlite:// URL; by default that is
    "sqlite://microcore.db", i.e. the working directory that also holds
    config.yaml. For PostgreSQL nodes the URL carries no file path, so
    the working directory is used. The directory is created if missing;
    when it is created here its mode is 0o700 on POSIX. A pre-existing
    directory (e.g. an operator-managed working directory) is NOT
    chmod'ed, so we never tighten permissions on host-managed folders."""
    global _SECRETS_DIR_CACHE
    if _SECRETS_DIR_CACHE:
        return _SECRETS_DIR_CACHE
    _d = os.getcwd()
    try:
        _url = (((config if config is not None else globals().get('CONFIG')) or {})
                .get('database', {}) or {}).get('url')
        if isinstance(_url, str) and _url.lower().startswith('sqlite://'):
            _raw = _url[len('sqlite://'):].strip().strip('"\'')
            if _raw:
                _d = os.path.dirname(os.path.abspath(_raw)) or os.getcwd()
    except Exception:
        pass
    try:
        _existed = os.path.isdir(_d)
        os.makedirs(_d, exist_ok=True)
        if not _existed and os.name != 'nt':
            os.chmod(_d, 0o700)
    except Exception:
        pass
    # Phase 6: warn if the data/secret directory lives in a cloud-synced folder.
    _dl = _d.lower()
    if ('onedrive' in _dl or 'dropbox' in _dl or 'google drive' in _dl):
        logger.warning("[DATA-PATH] Node data directory %s is inside a cloud-synced folder (OneDrive/Dropbox/Google Drive). "
                       "Files in this folder may sync to the cloud; keep secret files out of synced folders.", _d)
    _SECRETS_DIR_CACHE = _d
    return _d


def _write_secret_file(path, data: bytes) -> None:
    """AUTO-SECRETS-1: write a secret file atomically (temp file in the
    same directory, fsync, then os.replace) with 0o600 on POSIX. Windows
    has no POSIX file modes, so the chmod is skipped there (known
    limitation, recorded in the change report)."""
    _d = os.path.dirname(path) or "."
    _fd, _tmp = tempfile.mkstemp(prefix=".secret-", dir=_d)
    try:
        with os.fdopen(_fd, "wb") as _f:
            _f.write(data)
            _f.flush()
            os.fsync(_f.fileno())
        if os.name != 'nt':
            os.chmod(_tmp, 0o600)
        os.replace(_tmp, path)
    except BaseException:
        try:
            os.unlink(_tmp)
        except Exception:
            pass
        raise


def _read_secret_file(path) -> str:
    """AUTO-SECRETS-1: read a saved secret file ("" if absent/unreadable).
    Never logs the value."""
    try:
        if os.path.isfile(path):
            with open(path, 'rb') as _f:
                return _f.read().decode('utf-8').strip()
    except Exception:
        pass
    return ""


def _rpc_token_file_path(config=None) -> str:
    """AUTO-SECRETS-3: absolute path of the saved RPC bearer token file."""
    return os.path.abspath(os.path.join(_secrets_dir(config), "rpc_token"))


def _rpc_bearer_token(config) -> str:
    """RPC-AUTH-1 / AUTO-SECRETS-3: operator bearer token by precedence:
    MCX_RPC_TOKEN env > node.rpc_token config > saved <data dir>/rpc_token
    file (read once, then cached) > "" (unset; the startup check then
    generates one). Empty = unset. Never logs the token value."""
    try:
        _env = (os.environ.get("MCX_RPC_TOKEN", "") or "").strip()
        if _env:
            return _env
        _cfg = str((((config or {}).get('node', {}) or {}).get('rpc_token', "")) or "").strip()
        if _cfg:
            return _cfg
        global _RPC_TOKEN_FILE_CACHE, _RPC_TOKEN_FILE_TRIED
        if not _RPC_TOKEN_FILE_TRIED:
            _RPC_TOKEN_FILE_TRIED = True
            _saved = _read_secret_file(_rpc_token_file_path(config))
            if _saved:
                _RPC_TOKEN_FILE_CACHE = _saved
        return _RPC_TOKEN_FILE_CACHE or ""
    except Exception:
        return ""


def _generate_and_save_rpc_token(config) -> str:
    """AUTO-SECRETS-3: generate a strong RPC bearer token when none is
    configured, save it to <data dir>/rpc_token (0o600, atomic write;
    never written to config.yaml) and return it. The token must pass the
    same strength checks as anything an operator sets. To rotate it,
    delete the file and restart (rotation is manual). Returns "" when
    generation or persistence fails so the caller keeps its
    refuse-to-start path. Never logs the token value."""
    global _RPC_TOKEN_FILE_CACHE, _RPC_TOKEN_FILE_TRIED
    _tok = ""
    for _ in range(8):
        _tok = secrets.token_urlsafe(24)
        if len(_tok) >= 24 and not _is_weak_token(_tok):
            break
    else:
        logger.error("[RPC-AUTH] Could not generate a token that passes the strength checks (8 attempts). Refusing to start.")
        return ""
    try:
        _path = _rpc_token_file_path(config)
        _write_secret_file(_path, (_tok + "\n").encode("utf-8"))
        _RPC_TOKEN_FILE_CACHE = _tok
        _RPC_TOKEN_FILE_TRIED = True
        logger.warning(f"[RPC-AUTH] No RPC token configured. Generated one and saved it to {_path}. Read it from that file, or set MCX_RPC_TOKEN.")
        return _tok
    except Exception as e:
        logger.error(f"[RPC-AUTH] Generated an RPC token but could not save it to disk ({e}). Refusing to start.")
        return ""


_RPC_TRUST_BAD_LOGGED = False


# from "key present with any value, including explicit null" (must parse
_RPC_TRUST_ABSENT = object()


def _rpc_trust_loopback_raw(config):
    """Raw node.rpc_trust_loopback value (_RPC_TRUST_ABSENT = absent).
    Non-dict config or node section counts as absent (legacy default)."""
    node = config.get('node') if isinstance(config, dict) else None
    if not isinstance(node, dict):
        return _RPC_TRUST_ABSENT
    return node['rpc_trust_loopback'] if 'rpc_trust_loopback' in node else _RPC_TRUST_ABSENT


def validate_rpc_security_config(config) -> None:
    """RPC-LOOPBACK-STRICT-1: boot-time validation. Raises ValueError for a
    node.rpc_trust_loopback that is not a bool / "true" / "false" (CONFIG-BOOL-1
    rules), so a mistyped security flag fails clearly instead of silently.
    FP1-NULL-1: an absent key keeps the legacy default (no raise); an
    explicit null is malformed and raises like any invalid value."""
    _raw = _rpc_trust_loopback_raw(config)
    if _raw is _RPC_TRUST_ABSENT:
        return
    # must be rejected here, not passed through (it would silently trust).
    if _raw is None:
        raise ValueError("config node.rpc_trust_loopback must be a boolean (true/false), got None (explicit null is malformed; omit the key for the legacy default)")
    _strict_bool('node.rpc_trust_loopback', _raw, True)


def _rpc_trust_loopback_effective(config) -> bool:
    """RPC-LOOPBACK-STRICT-1: strict parse; absent -> True (legacy default).
    An INVALID value fails CLOSED (loopback not trusted; bearer token
    required) — it used to be bool(...), so the string "false" kept loopback
    trusted, and any parse error returned True."""
    global _RPC_TRUST_BAD_LOGGED
    # fail closed (loopback not trusted, bearer required).
    _raw_eff = _rpc_trust_loopback_raw(config)
    if _raw_eff is _RPC_TRUST_ABSENT:
        return True
    if _raw_eff is None:
        if not _RPC_TRUST_BAD_LOGGED:
            _RPC_TRUST_BAD_LOGGED = True
            logger.error("[RPC-AUTH] config node.rpc_trust_loopback is null (malformed) — failing closed: loopback NOT trusted, bearer token required")
        return False
    try:
        return _strict_bool('node.rpc_trust_loopback', _raw_eff, True)
    except ValueError as _e:
        if not _RPC_TRUST_BAD_LOGGED:
            _RPC_TRUST_BAD_LOGGED = True
            logger.error(f"[RPC-AUTH] {_e} — failing closed: loopback NOT trusted, bearer token required")
        return False


# normalisation (F1). Never logged.
_TOKEN_WEAK_SUBSTRINGS = (
    "changeme", "replaceme", "placeholder", "yourtoken", "yoursecret", "example",
)


def _normalise_token(token: str) -> str:
    """Normalise a bearer token for weakness checks: casefold and remove
    "_", "-", " ". Never logs the token value."""
    return token.casefold().replace("_", "").replace("-", "").replace(" ", "")


def _is_weak_token(token: str) -> bool:
    """Return True if token is a placeholder or trivially weak value.

    Checks the normalised token for known placeholder substrings and for
    fewer than 10 distinct characters. Never logs the token value."""
    if not token:
        return False
    normalised = _normalise_token(token)
    for bad in _TOKEN_WEAK_SUBSTRINGS:
        if bad in normalised:
            return True
    if len(set(normalised)) < 10:
        return True
    return False


def _bind_is_loopback_only(bind_ip) -> bool:
    """True if bind_ip refers only to loopback interfaces (IPv4/IPv6).

    0.0.0.0 / :: (wildcard) and any non-loopback IP -> False (token required).
    Named loopback hosts (localhost, ...) count as loopback. Unresolvable
    hostnames fail closed (token required)."""
    if not bind_ip or not isinstance(bind_ip, str):
        return False
    s = bind_ip.strip()
    if s.lower() in ("localhost", "ip6-localhost", "ipv6-localhost"):
        return True
    try:
        return ipaddress.ip_address(s).is_loopback
    except ValueError:
        try:
            infos = socket.getaddrinfo(s, None, type=socket.SOCK_STREAM)
        except OSError:
            return False  # fail-closed: unknown bind -> require token
        return bool(infos) and all(
            ipaddress.ip_address(info[4][0]).is_loopback for info in infos
        )


def validate_rpc_startup_token(config) -> None:
    """Fail startup when RPC needs a bearer token but none is usable (F1-F3).

    A token is REQUIRED when the bind is non-loopback OR when loopback is
    not trusted (_rpc_trust_loopback_effective is false). Loopback bind with
    loopback trusted and no token still starts — AUTO-SECRETS-3: nothing is
    generated in that case, so local use needs zero configuration.

    AUTO-SECRETS-3: if a token is required and none is configured (MCX_RPC_TOKEN
    env, node.rpc_token, or the saved rpc_token file), one is generated once
    and saved to <data dir>/rpc_token — never into config.yaml. The generated
    token passes the same checks as any operator-set token; nothing is skipped.

    Rejects (when a token is required):
      * a blank/missing token that could not be auto-generated or saved —
        actionable message naming the 0.0.0.0 default and how to set a real
        secret,
      * any normalised token containing a placeholder substring
        (changeme/replaceme/placeholder/yourtoken/yoursecret/example),
      * any token with fewer than 10 distinct characters,
      * any token shorter than 24 characters.

    Loopback-only binds with loopback trusted may run without a token.
    The effective token honours MCX_RPC_TOKEN (env wins) over node.rpc_token.
    Fail closed: a clear error and non-zero exit before the API listener
    opens. Never logs the token value."""
    _rpc_bind = str((config or {}).get('node', {}).get('rpc_bind_ip', RPC_BIND_IP) or RPC_BIND_IP)
    _loopback_only = _bind_is_loopback_only(_rpc_bind)
    _trust_loopback = _rpc_trust_loopback_effective(config)
    _token_required = (not _loopback_only) or (not _trust_loopback)

    if not _token_required:
        return

    _token = _rpc_bearer_token(config)
    if not _token:
        # AUTO-SECRETS-3: no operator token anywhere (env, config, saved
        _token = _generate_and_save_rpc_token(config)
    if not _token:
        logger.error(
            "[RPC-AUTH] JSON-RPC HTTP API is bound to %s (not loopback-only) "
            "with no API access secret. This is NOT related to deploying "
            "fungible tokens — it only protects POST /rpc from the network. "
            "For a local node: set node.rpc_bind_ip: 127.0.0.1. "
            "To expose RPC on the LAN: set MCX_RPC_TOKEN or node.rpc_token "
            "to a >=24-char random secret. Refusing to start.", _rpc_bind)
        sys.exit(1)
    if "CHANGE_ME" in _token:
        logger.error("[RPC-AUTH] Configured bearer token is a placeholder (contains 'CHANGE_ME'). "
                     "Refusing to start. Set MCX_RPC_TOKEN / node.rpc_token to a real secret.")
        sys.exit(1)
    if _is_weak_token(_token):
        logger.error("[RPC-AUTH] Configured bearer token is a placeholder or weak value. "
                     "Refusing to start. Set MCX_RPC_TOKEN / node.rpc_token to a "
                     ">=24-char random secret.")
        sys.exit(1)
    if len(_token) < 24:
        logger.error("[RPC-AUTH] Configured bearer token is %d characters (< 24). Refusing to start.",
                     len(_token))
        sys.exit(1)


def _rpc_remote_authorized(request, config) -> bool:
    """RPC-AUTH-1: loopback clients are always trusted (local wallets and
    tools work unchanged, no token needed). Non-loopback clients must
    present the configured Bearer token, compared constant-time. Unknown
    remote address or no token configured -> denied. Pure apart from env/
    config reads; unit-testable with request fakes (needs .remote and
    .headers.get)."""
    try:
        if ipaddress.ip_address(request.remote or "").is_loopback:
            # 127.0.0.1 bypasses the bearer gate). Proxy deployments must
            if _rpc_trust_loopback_effective(config):
                return True
    except ValueError:
        pass
    except Exception:
        return False
    want = _rpc_bearer_token(config)
    if not want:
        return False
    try:
        auth = (request.headers.get("Authorization", "") or "").strip()
    except Exception:
        return False
    if not auth.lower().startswith("bearer "):
        return False
    try:
        return hmac.compare_digest(auth[7:].strip(), want)
    except Exception:
        return False

